'use strict';
const CAST={l:'リーネ',t:'ティア',s:'セリオン',g:'ガレス',y:'ユーリ',n:'ネイア',r:'種族の代表'};
const FRAGMENTS={record:['宰相の公文書','歴代の討伐記録には、異なる時代、異なる種族の名があった。いずれにも「ゼルグ」の語が混ざる。'],song:['辺境の子守唄','「こわいひとも、ゆめをみる」。名を失った誰かが、普通の暮らしを願っていた。'],stone:['六種族の碑文','近い者、被害の小さい者へ。そう読める例が残るが、席の移り先を定める規則の証明ではない。'],witness:['魔族の証言','ヴァルゼンは人間を憎んでいなかった。覚えている者の声まで、世界は復讐として退けた。'],contact:['祈りの余白','古い祈りと現在の祭儀に同じ空白がある。一方的に祈るのではなく、神に返答を求める場所。']};
const ENDINGS={bad:{no:'I',name:'誰もいない道',label:'バッドエンド',hint:'路地の声を聞きに戻れば、出会える人がいる。',desc:'倒しても、また次の誰かが災厄になる。隣にはもう、誰もいなかった。'},harmony:{no:'II',name:'静かな調和',label:'調和エンド',hint:'誰かに引き受けさせる以外の道を、旅の中で探そう。',desc:'世界は平和を取り戻したと言った。その言葉の外で、ひとりの少女が消えていった。'},sacrifice:{no:'III',name:'君の敵になる',label:'犠牲エンド',hint:'大切な人を守る覚悟だけでは、席の仕組みは変わらない。',desc:'世界を救うことを諦めた。世界が彼女を恐れるのなら、俺もその側に立つ。'},collapse:{no:'IV',name:'砕けた天秤',label:'崩壊エンド',hint:'席を壊す前に、各種族と仲間が自分の意志で選ぶ必要がある。',desc:'ひとりで終わらせたつもりだった。共通の敵を失った世界に、いくつもの戦火が灯った。'},true:{no:'V',name:'名を呼ぶ朝',label:'真のエンド',hint:'恐怖の代わりに信頼を選んだ。それは、これからも選び続けるもの。',desc:'保証された平和は、もうない。それでも、この不確かな朝を、俺たちは一緒に選んだ。'},god:{no:'VI',name:'神のいない空',label:'神を嵌めるエンド',hint:'過去と現在の記録、種族の関係、言葉にしなかった信頼が重なった。',desc:'人が災厄として討たれる連鎖は終わった。名を失いゆく神のことも、俺たちは覚えている。'}};
const STORY={};
function scene(id,ch,title,lines,next,choices){STORY[id]={ch,title,lines:lines.map(x=>typeof x==='string'?['',x]:x),next,choices};}
function choice(text,to,rel={},fragments=[],flags={}){return{text,to,rel,fragments,flags};}

// 全編統合稿 v1。場面と本文は同梱の原稿に対応。
scene("prologue","PROLOGUE","名を失う夜",[["","刃を引くと、夜が静かになった。"],["","地面の揺れが止まった。誰も声を上げない。荒い息づかいだけが、暗がりに残っていた。"],["","剣の柄を握った手は、まだ震えていた。"],["？？？","……どうして……連れて……きたんだよ……。"],["","答えようとした声は、喉の奥で潰れた。"],["","倒れた影が、俺ではない誰かのほうへ顔を向けた。輪郭がにじんで、その顔は見えない。"],["？？？","……エ……ハ……××……て……ダ……な……。"],["","かすかな笑い声が、遠のいていく。誰かが息を吸ったきり、黙り込んだ。"],["","俺の袖を掴んでいた指が、ゆっくりと緩んでいく。俺は動かず、その手が離れるのを待った。"],["","何も、終わっていなかった。"]],"alley",null);
scene("alley","CHAPTER 01","旅立ちの日",[["","鐘が鳴っている。\n一つ、二つ。\n焼けたパンの匂いがして、目の前を荷車が横切った。"],["","荷車が通り過ぎると、通りの向かいに白い服の少女が見えた。孤児院の門の前にいる。"],["","白い服。縫い直した跡のある鞄。胸元の小さな飾りを、一度だけ確かめる。"],["","門の前で、子どもが少女の手を握っていた。少女がしゃがんで何か話すと、ようやく手を離した。"],["","子どもたちの後ろにいた女性が、少女を抱きしめた。少女も、その背中へ腕を回した。"],["女性","体を大事にね"],["リーネ","……はい。お世話になりました"],["","女性は少女が門を出るまで見送った。少女は振り返り、深く頭を下げた。"],["","俺は通りを挟んだ向かい側で、買っておいた冷めたパンを半分に折った。"],["","無事に出てきた。それだけ確かめればよかった。パンを食べ終えたら、西の水路へ向かうつもりだった。"],["","少女は通りの真ん中で足を止めた。右を見て、左を見て、鞄を持ち直す。"],["","右へ一歩。けれど、すぐに足が止まる。"],["","また荷車が、俺と少女の間を通った。視界が開けたとき、彼女の前には男が二人立っていた。"],["男","へえ、回復が使えんのか。なら来いよ。ちょうど一人、抜けちまってな。"],["","少女は頭を下げた。男の一人が鞄へ手を伸ばす。彼女は鞄を抱え直した。"],["リーネ","持てます。仕事のことを、先に教えてください。"],["男","んなもん、後でいいだろ。ほら、仲間を待たせんな。"],["","差し出された手を取らず、彼女は男たちの後ろを歩いた。"],["","少女は男たちの話に、何度も頷いていた。笑おうとしているが、口元だけがぎこちない。"],["","俺は食べかけのパンを布に包んだ。男の一人が、少女の背中を押して歩かせる。"],["","宿の看板を通り過ぎ、男たちは倉庫の脇の細い路地へ入っていった。あそこは、行き止まりだ。"],["","三人が角を曲がった。通りの音に、笑い声が混じる。"],["男","おい、ただで仲間に入れると思ってんのか？　金がねえなら、その飾りをよこせ。"],["リーネ","お金が必要なら、最初に言ってください。私は、まだ入るとは――。"],["","声が途切れた。続けて、硬いものが壁にぶつかる音がした。"],["","俺は足を止めた。通りの先では、西門へ向かう荷馬車が動き始めていた。"]],null,[{"text": "路地へ戻り、声の主を確かめる", "to": "rescue", "rel": {"l": 1}, "fragments": [], "flags": {}}, {"text": "記録の探索を優先し、町を離れる", "to": "lonely", "rel": {}, "fragments": [], "flags": {}}]);
scene("rescue","CHAPTER 01","差し出された手",[["","路地に戻ると、男の一人が、少女から取り上げた鞄を壁に押しつけていた。"],["リーネ","返してください。中には、薬も入ってるんです。"],["男","うるせえな。人の話を聞けっつって――。"],["","鞄を押さえている男の手首を掴んで捻った。男の膝が石畳につく。"],["","もう一人が腰の剣に手をやる。その手が柄に届く前に、俺は上着の裾をめくり、腰の短剣を鞘ごと見せた。"],["","男の目が、鞘に刻まれた紋章で止まった。"],["ミナト","それなら、しかるべき所で話そうか。"],["男","ちっ……大げさなんだよ。ちょっとからかっただけだろうが。"],["ミナト","じゃあ、鞄を返せば終わる。"],["","手首を放すと、男は腕を抱えて立ち上がった。何か吐き捨て、仲間と一緒に逃げていった。"],["","少女は俺を見ていなかった。石畳にしゃがみ、鞄から薬の小瓶を取り出して、震える指で一本ずつ並べている。"],["ミナト","怪我は。"],["リーネ","私は……大丈夫です。"],["","彼女は割れた瓶の底を拾い、布で包んだ。薬の匂いが路地に残った。"],["リーネ","待ってください。どうして、助けてくれたんですか。"],["ミナト","頼まれたからだ。"],["","少女は俺の顔と、腰の短剣とを見比べた。"],["ミナト","……もう大丈夫だ。俺は行くぞ。"],["","彼女が口を開く前に、短剣を上着の下へ戻した。"],["リーネ","お礼を、何も……。"],["ミナト","次は、すぐについていくな。仕事の話でも、まず人のいる所で聞け。"],["","立ち去ろうとすると、後ろから石畳を踏む足音がついてきた。"],["","一つ目の角を曲がっても、二つ目の角を曲がっても、足音は止まらない。"],["リーネ","私、リーネです。"],["ミナト","そうか。"],["リーネ","まだ、お名前を聞いてません。"],["ミナト","ミナト。"],["","名前を覚えるように、彼女の唇が動いた。"],["リーネ","ミナトさん。西門へ行くんですか。"],["ミナト","そうだ。"],["リーネ","私、今日、あそこを出たばかりで……。仕事を探してるんです。薬のことなら、少し分かるので。"],["","歩く速さは変えなかった。少し遅れていた靴音が、また隣へ追いついた。"],["ミナト","会ったばかりの相手に、何でも話すな。俺にもだ。"],["リーネ","……はい。"],["","口をつぐんだリーネが、ふと俺の左手を見た。"],["","袖口に血がにじんでいた。さっき男の手首を捻ったとき、爪で引っかかれたらしい。彼女が鞄から細い布を取り出す。"],["リーネ","少しだけ。じっとしていてください。"],["","彼女の掌から温かな光がこぼれ、傷に触れた。血が止まると同時に、彼女の指先が小さく震えた。"],["ミナト","それくらい、布を巻けば済む。"],["リーネ","……はい。でも、させてください。"],["","傷が閉じた。彼女は布をしまい、今度は正面から俺を見た。"],["","俺が歩き出すと、彼女も鞄を抱え直した。"],["ミナト","……まだ、何か用か。"],["リーネ","私も、一緒に連れていってもらえませんか。"],["ミナト","やめとけ。俺についてきても、安全じゃない。"],["リーネ","……足手まといには、ならないようにします。薬のことなら、少しは――"],["ミナト","そういう話じゃない。俺は、人を助けて回ってるわけじゃないんだ。"],["","少女は俯いた。俺は背を向けたが、足が出なかった。"],["リーネ","行きたい所が、あるんです。"],["","振り返ると、彼女はまだそこにいた。"],["ミナト","……だったら、なおさらだ。もっとましな道を選べ。"],["","彼女は一度、口を閉じた。"],["リーネ","私には、どっちがましか、まだ分かりません。でも……何も聞かずに決めないでください。"],["ミナト","……。"],["リーネ","お礼だけじゃないです。一緒に行きたいんです。途中まででも。"],["","西門の鐘が鳴った。俺は門の外へ続く道と、彼女の靴とを見比べた。"],["","旅用に手直しした古い靴だった。"]],null,[{"text": "「自分で選んだ道なら、一緒に歩こう」", "to": "brother", "rel": {"l": 2}, "fragments": [], "flags": {}}, {"text": "「危険なときは、俺の言うとおりに」", "to": "brother", "rel": {}, "fragments": [], "flags": {}}]);
scene("brother","CHAPTER 01","探している人",[["","門を出てしばらくは、リーネの靴音だけが早かった。"],["","俺が立ち止まるたび、彼女も止まる。道端の草まで、見慣れないもののように眺めていた。"],["ミナト","靴、痛くないか。"],["リーネ","まだ大丈夫です。"],["ミナト","まだ、ってことは、あとで痛くなるな。"],["リーネ","……少しだけ、かかとが。"],["","道端の石に座ってもらい、俺は自分の鞄から当て布を取り出した。"],["ミナト","もっと早く言えよ。皮が剥けたら、明日も痛むぞ。"],["リーネ","はい。"],["","リーネは布を小さく折り、靴のかかとの内側に当てた。余った布を俺に返そうとするので、その手を押し戻す。"],["","水を飲んでいる間、彼女は何かを尋ねかけ、二度やめた。"],["ミナト","行きたい場所っていうのは。"],["リーネ","場所は、まだ分からないんです。人を探していて。"],["","指が、胸元の飾りから離れた。"],["リーネ","年の離れた兄がいます。私が小さい頃、旅に出て……。"],["リーネ","たぶん、冒険者になっていると思うんです。カイルという冒険者をご存じですか。"],["","俺は水筒の栓を締めた。乾いた音が、少し長く響いた。"],["","街道を荷車が通り過ぎた。車輪の跡に、砂が落ちる。"],["ミナト","探している人間は、俺にもいる。"],["リーネ","そう、なんですね。"],["","リーネは膝の上で手を重ねた。"],["リーネ","兄の顔、ちゃんと思い出せないんです。笑っていたことは、覚えてるんですけど。"],["リーネ","声も。覚えているつもりで考えると、違う声みたいになって。"],["ミナト","最後に会ったのは。"],["リーネ","ずっと小さい頃です。でも、出ていくときの言葉は、覚えています。"],["リーネ","兄ちゃんが世界を平和にしてくるから、って。"],["","風が服の裾を揺らした。彼女は、裾の同じところを指で何度も伸ばした。"],["ミナト","……それで、探しに出るのか。"],["リーネ","ちゃんと食べてるかなって。……あの人、自分の分まで私によこすから。"],["","少し笑ってから、リーネは俯いた。\n「今もそうなのかな」と、小さく付け足す。"],["リーネ","ミナトさんの探している人にも、会えるといいですね。"],["","水筒を鞄へ戻した。"],["ミナト","そうだな。"],["","立ち上がって歩き始めると、今度の靴音は、さっきほど急いでいなかった。"]],"scholar",null);
scene("scholar","CHAPTER 02","言葉の向こう",[["","水車はぴくりとも動いていなかった。その脇、水門の横に据えられた古い石板に、エルフの男が顔を近づけている。"],["セリオン","触らないでください。そこは、まだ写していません。"],["","男の背後へ回りかけたリーネが、足元の石片を踏みかけて、片足を浮かせたまま止まった。"],["ミナト","セリオンか。ガレスの紹介で来た。"],["セリオン","その短剣……。お待ちしていました。"],["セリオン","お二人で旅を？　ガレスからは、ミナトさんが一人で来ると聞いていたもので。"],["リーネ","リーネです。あの、足を下ろしても。"],["セリオン","失礼。セリオンと申します。そちらの石は構いません。"],["","差し出された手には、乾いた墨がついていた。本人は気づいていないらしい。"],["ミナト","いや。ここまでだ。"],["","鞄を持ち直した。隣で、リーネも足を下ろす。"],["ミナト","……お前は、町で仕事を探すんだろ。"],["リーネ","探します。"],["ミナト","なら――"],["リーネ","でも、まだここでは決めていません。"],["ミナト","俺について来ても、仕事は見つからないぞ。"],["リーネ","そこまでは、頼んでいません。"],["","言ってから、リーネは目を伏せた。水路の先へ一度目を向ける。"],["","それでも、俺の隣からは動かなかった。"],["","セリオンは問い返さず、石板へ視線を戻した。"],["","水車小屋の主人が、俺たちへ声をかけた。"],["水車小屋の主人","学者先生。読めたかい。昼までに粉を挽きたかったんだが。"],["セリオン","読めました。ただ、この一語が。開けるのか、閉めるのか……肝心なところだけ削れています。"],["","石板の隣に、水門を動かす鉄の輪があった。輪を回すと、水路を塞ぐ板が上下する仕組みらしい。主人が実際に回してみせたが、板は動かなかった。"],["ミナト","先に、上流からの水を止められるか。"],["水車小屋の主人","ああ。少し待っていてくれ。"],["","主人が戻ってきた頃には、水の流れが弱まっていた。板の手前には、まだ水が溜まっている。"],["","リーネが水路の反対側へ回り、縁から覗き込んだ。"],["リーネ","板が斜めになっています。こっちの端が、溝に引っかかっているみたいです。"],["ミナト","そっちからは見えるのか。"],["リーネ","はい。ミナトさんの方からだと、陰になります。"],["","彼女の指す場所を確かめ、主人から板を押すための長い棒を借りた。"],["ミナト","上げようとして、余計に引っかかったんだな。いったん、少し下げてくれ。"],["水車小屋の主人","下げるのか？"],["ミナト","ああ。押しつけてる力を抜きたい。その間に、俺が板をまっすぐに戻す。"],["","セリオンが輪へ手を掛けた。リーネは、板の端が見える場所に残った。"],["","輪が少し戻る。俺は棒の先を板の端へ当て、ゆっくり押した。濡れた棒が手の中で滑り、踏み直した石から冷たい水が靴へ入った。"],["リーネ","もう少し下です。……そこ。溝に戻りました。"],["ミナト","よし。今度は上げてみてくれ。"],["","輪が回り、板が持ち上がった。溜まっていた水が、その下を流れ出す。"],["","主人が上流の水を戻すと、流れが勢いを増した。水車がゆっくり動き始めた。主人は小屋へ駆け込み、すぐに笑いながら戻ってきた。"],["水車小屋の主人","回った！　助かったよ。"],["","リーネは濡れた袖を絞っていた。俺の視線に気づくと、ほんの少し口元を緩めた。"],["ミナト","よく見つけた。"],["リーネ","そこからは、見えなかっただけです。"],["","セリオンは回り始めた水車と、石板を見比べていた。"],["セリオン","先ほどの「力を抜く」とは？　もう少し聞かせていただけますか。"],["ミナト","力には向きもあるだろ。同じ強さで押しても、こっちとあっちじゃ、結果が変わる。"],["セリオン","向きと、強さを分けて扱う？"],["ミナト","……俺がいた所では、そう習った。押すのと引くのじゃ、釣り合いが違う。"],["セリオン","習った？　誰に。どういう言葉で？　説明してください。最初から。"],["","革表紙の手帳が鼻先まで迫った。俺は一歩下がり、石板へ踵をぶつけた。"],["ミナト","まず、その手帳を離してくれ。"],["","リーネが口元を袖で隠した。セリオンは手帳を引いたが、筆はしまわなかった。"],["","夕方。小屋の主人に食卓を借り、買っておいたパンと根菜を広げた。"],["セリオン","古い言葉を読む旅、と伺っています。どこまでの土地を回る予定ですか。"],["ミナト","王都から、その先も。国も言葉も違う記録を読みたい。俺一人じゃ、歯が立たない。"],["セリオン","似た話でも、同じ出来事とは限りませんよ。"],["ミナト","それを確かめたい。"],["セリオン","……災厄についての記録も、含みますか。"],["","俺はパンをちぎる手を止めた。"],["ミナト","……ああ。"],["セリオン","あなたは、その脅威を見たことがある。"],["ミナト","……ああ。"],["","セリオンは俺の顔を見た。それから、広げかけた手帳を閉じた。"],["セリオン","私も行きましょう。"],["ミナト","小屋の方は、いいのか。"],["セリオン","写しは取りました。こちらで確かめられることも、ひとまずは。"],["","手帳を袋へ入れかけ、また取り出す。水車のそばで書いた頁を開いた。"],["セリオン","先ほどのお話ですが。釣り合っていても、力がなくなったわけではないのですね。"],["ミナト","……ああ。"],["セリオン","では、動かないものにも――"],["","そこで言葉を切り、俺の手元を見た。ちぎったパンが、まだ残っている。"],["セリオン","失礼。食後にしましょう。"],["ミナト","旅の間も、それか。"],["セリオン","ほかにも伺いたいことがあります。"],["","リーネが小さく笑った。セリオンは何がおかしいのか分からない顔で、空いた皿を引き寄せた。"],["","食卓の向こうで、水車が回っている。三人分の皿は、まだ片づけられていなかった。"]],null,[{"text": "眠くなるまで、別の世界の言葉を話す", "to": "arena", "rel": {"s": 2}, "fragments": [], "flags": {"physics": true}}, {"text": "解読に必要な話だけして休む", "to": "arena", "rel": {"s": 1}, "fragments": [], "flags": {}}]);
scene("arena","CHAPTER 02","負けず嫌いの同行者",[["","翌朝、街道へ出る前に、水車小屋から町へ戻った。井戸へ向かう途中で、リーネが俺の袖を引いた。"],["リーネ","昨日は、お昼までにここを出るはずでしたよね。"],["ミナト","そうだな。"],["","水車の音が、まだ耳の奥に残っている。セリオンは歩きながら、もう手帳を開いていた。"],["セリオン","ご心配なく。王都には間に合わせます。"],["リーネ","それなら、少し休憩しませんか。水も、補充したいです。"],["","井戸の向こうから、歓声が上がった。広場の端に、縄で囲った小さな闘技場がある。"],["","虎の縞を持つ獣人の少女が、木剣を打ち落とした。相手の男が両手を上げる。"],["審判","そこまで。勝者、青の組。"],["","少女が、自分の腕に結んだ赤い布――赤組の印を見た。"],["ティア","……はあ？　あたし、今、勝っただろ！"],["審判","先に場外へ出た。規則だ。"],["ティア","出てない！　足跡、ちゃんと見ろよ！"],["","縄の内側に、爪の跡が残っていた。審判はそこを靴で踏み消し、次の試合を呼んだ。"],["男","負けを認めろよ。獣人はいつも、声だけでかいな。"],["","ティアが男へ一歩寄った。係の者が、間に長い棒を入れる。"],["係の男","判定が不服なら退場だ。賞金も出せん。"],["リーネ","手から、血が出てる。"],["ミナト","待て。まだ、試合の話が終わってない。"],["リーネ","……でも、血が。布を渡すだけですから。"],["","リーネが縄の前へ進み、少女へ布を見せた。"],["リーネ","傷を、見せてもらってもいいですか。"],["ティア","これくらい、平気だ。"],["リーネ","木の欠片が入ってます。そのまま握ると、深くなります。"],["","少女は自分の掌を見た。しばらくして、無言で手を差し出した。"],["","俺は賞金を配っている机へ回った。帳簿には、試合の組み合わせと払い戻しの額が並んでいる。"],["ミナト","帳簿、見せてくれ。今の試合のところだ。"],["係の男","負けは負けだ。聞いてなかったのか。"],["セリオン","その行、試合が終わる前から書かれていましたね。"],["","係の男が帳簿を閉じた。セリオンは、その手を見ていた。"],["セリオン","試合前です。客がお金を出していた時、もう青の勝ちと書いてありました。"],["審判","見間違いだ。よそ者が口出すんじゃねえ。"],["ミナト","じゃあ、開いて確認すれば済む。"],["","審判が俺の肩を押した。その拍子に、審判の袖から銀貨が落ちる。勝ったことになった男が、銀貨へ靴を寄せた。"],["","落ちた銀貨を俺が踏むと、男は足を引いた。"],["ミナト","さっきは、その男も机の前にいたな。いいから開けろ。みんなに見せろ。"],["","縄の向こうで、観客が机の前へ寄ってきた。"],["観客","俺も赤に賭けたぞ。足跡を消したの、見てたからな。"],["","別の客が、広場の見回りを呼びに行った。係の男は、閉じた帳簿から手を離さなかった。"],["","見回りが帳簿を開かせると、まだ始まっていない試合にも勝ち負けがついていた。\n金を返せという声が、一斉に上がった。"],["","俺たちが広場を出られた頃には、昼を回っていた。少女は戻った参加料を、何度も数えていた。"],["","少女が小銭を袋にしまう。隣でリーネが、包帯の結び目をそっと押さえた。"],["ティア","助けろなんて、言ってないぞ。"],["リーネ","はい。手を見せてもらっただけです。"],["ティア","あんたじゃなくて、そっちだ！"],["ミナト","俺は帳簿を見せろと言っただけだ。"],["","ティアは口を開き、閉じた。尾の先が、石畳を一度叩いた。"],["ティア","……借りは返す。あたしはティア。あんたは？"],["ミナト","ミナト。こっちはリーネ、セリオンだ。"],["ティア","あんたも、あいつらに腹が立ったのか？"],["セリオン","せめて、試合が終わるまで待ってから書けばよかったのに。"],["","ティアが目を丸くした。俺もセリオンを見たが、顔はいつもどおりだった。"],["ティア","借りっぱなしは嫌なんだよ。明日の朝飯は、あたしが作る。"],["ミナト","作れるのか。"],["ティア","当たり前だろ。これくらいはさせろ。"],["リーネ","手伝います。二人で作った方が、早いですから。"],["リーネ","材料なら、さっき買いました。みんなで食べられます。"],["","リーネは、もう一度材料を数えている。"],["ティア","いいぞ。寝坊すんなよ。"],["","その晩、町の外の野営地に、三人分だった荷物が四人分並んだ。"],["ティア","それで、どこへ行くんだ？"],["ミナト","王都。古い記録を集めてる。"],["ティア","ふうん。あたしも、そっちだ。途中まではついてってやる。"],["ミナト","明日の朝飯は、任せた。"],["ティア","借りは、朝飯で返す。"],["","夜明け前、火の匂いで目が覚めた。ティアが鍋の前にしゃがんでいた。"],["ティア","起きたか。粥、もうすぐだ。"],["リーネ","まだ、火が強いです。薪を少し減らしましょう。"],["ティア","早くできた方が、あったかいうちに食えるだろ。"],["","そのとき、焦げた匂いがした。"],["ティア","……底、やっちまった。"],["リーネ","上の方は、大丈夫です。焦げた所を混ぜなければ。"],["","リーネが焦げていない上の方だけを、別の器へ移した。ティアは止めかけたが、その手を下ろした。"],["ティア","……悪い。"],["リーネ","味は、ちゃんと出てます。"],["","ティアは器を見つめたまま、包帯の巻かれた手を引っ込めた。"],["ミナト","痛むなら、鍋は持つな。器を並べてくれ。"],["ティア","痛くない。……器なら、並べてやる。"],["","四つの器を並べると、ティアが一つずつ覗き込んだ。焦げの少ない粥から、そっとリーネの前へ押している。"],["セリオン","そろそろ出ませんと。渡し船が出てしまうと、橋まで回り道ですよ。"],["ミナト","分かってる。"],["","リーネはまだ匙を取らない。ティアも座ったままだ。俺は広げた地図から、二人へ目を上げた。"]],null,[{"text": "焦げた粥も、四人で分ける", "to": "court-road", "rel": {"l": 1, "t": 2}, "fragments": [], "flags": {}}, {"text": "旅の規律を優先し、先を急ぐ", "to": "court-road", "rel": {"t": 1}, "fragments": [], "flags": {}}]);
scene("court-road","CHAPTER 03","白い城壁",[["", "王都の城壁が見えたのは、旅に出て五日目だった。"], ["", "道端の草が石畳に変わる。荷車が増え、隣を歩いていたリーネが少し後ろへ下がった。"], ["ミナト", "人が多いな。はぐれたら、門のところで待ってろ。"], ["ティア", "はぐれるかよ。そんな子どもじゃあるまいし。"], ["", "言いながら、ティアはリーネの鞄をひょいと持ち上げた。"], ["リーネ", "あ、自分で持てます。"], ["ティア", "紐。ほどけかけてるぞ。"], ["", "リーネが結び直す間も、ティアは鞄を離さなかった。"], ["", "門の前では、兵が荷を確かめていた。俺たちの番になると、槍の柄が半歩前へ出た。"], ["門兵", "用向きは。"], ["ミナト", "宰相に会いに。"], ["", "門兵は俺の上着を見て、それから靴へ目を落とした。"], ["", "短剣を見せると、背筋が伸びた。奥の兵に声をかけ、今度は馬車を通す方の門を指す。"], ["門兵", "こちらへ。ご案内します。"], ["", "ティアが俺の顔を覗き込んだ。"], ["ティア", "あんた、本当に何者なんだ？"], ["ミナト", "知り合いがいるだけだ。"], ["ティア", "知り合いで、あの門が開くのかよ。"], ["", "門の内側から、白い塔が見えた。リーネは塔ではなく、短剣をしまう俺の手を見ていた。"]],"court",null);
scene("court","CHAPTER 03","机の向こうの旧友",[["","案内された部屋では、扉の前にまで書類が積まれていた。"],["","青い上着の男が、机から顔を上げた。"],["ガレス","遅い。"],["ミナト","来る日までは、決めてなかっただろ。"],["ガレス","だから毎日、使いを待たせた。"],["","机の脇にいた若い書記が、俺たちを見てからガレスを見た。ガレスは片手で下がるように示す。"],["ミナト","また飯を抜いたのか。"],["ガレス","食べた。"],["","皿の上で、切った果物が乾いていた。俺が見ると、ガレスは書類を一枚、皿を隠すように立てた。"],["ガレス","セリオン殿。突然の依頼にもかかわらず、礼を言う。"],["セリオン","こちらこそ。実に興味深い道中でした。"],["ガレス","……それは何よりだ。"],["","俺を見る目に、少し疑いが混じった。"],["リーネ","リーネと申します。"],["","ガレスの手が、書類の端で止まった。"],["ガレス","……ガレス・ロウェルだ。そちらは。"],["ティア","ティア。堅苦しい挨拶は苦手なんだ。悪いな。"],["ガレス","構わん。座ってくれ。"],["","椅子は二脚しかなかった。ガレスは廊下へ出て、戻ってきた書記と一緒に椅子を運んだ。"],["ティア","偉い奴って、自分で運ぶんだな。"],["ガレス","私が使う部屋だ。椅子の場所くらい分かる。"],["","リーネが慌てて立ちかけたので、俺は隣の椅子を引いた。"],["","四人が座ると、部屋は急に狭くなった。"],["","ガレスは俺の前に、古い革表紙の冊子を置いた。"],["","ガレスは冊子から手を離したが、話し始めなかった。"],["","ティアが椅子を少し引いた。隣のリーネの鞄が、脚に挟まっていた。"],["ティア","ほら。こっちに置けばいいだろ。"],["リーネ","ありがとうございます。"],["","セリオンは膝の上に手帳を広げていた。二人のやり取りに顔を上げ、また紙へ目を落とす。"],["","ガレスの目が三人をたどり、俺のところで止まった。"],["ミナト","……なんだ。"],["ガレス","いや。"],["","口元がわずかに緩んだ。俺が見ていることに気づくと、ガレスは冊子を開いた。"],["","冊子の中には、紙の色も大きさも違う書き写しが挟まれていた。ある頁には川の絵、ある頁には焼けた門が描かれている。"],["ガレス","こちらは河口の都市。こちらは山の向こうの国だ。百年以上、時代も違う。"],["","ティアが机の上を覗き、次に、まだ開かれていない冊子の厚さを見た。"],["ティア","……長くなるのか、これ。"],["ミナト","たぶんな。"],["ティア","外、見てきていいか？"],["","ガレスが扉の脇を指した。"],["ガレス","廊下までは構わん。その先は兵に聞いてくれ。"],["","ティアはすぐに立った。リーネが少し腰を浮かせたが、俺を見て座り直した。"],["","セリオンが二枚を並べた。片方の文字を指でなぞり、もう片方へ移す。"],["セリオン","どちらにも、ゼルグ。"],["セリオン","片方だけ、後から書き足した跡はありませんか。"],["ガレス","それも調べさせた。少なくとも、ここで手を加えたものではない。"],["","次の紙には、顔のない人影が描かれていた。丸い耳と尾だけが、妙にはっきりしている。"],["","隣の紙の人影には、羽があった。"],["ミナト","……獣人と、鳥人か。"],["ガレス","ああ。討たれた側だ。"],["","セリオンが冊子へ手を伸ばした拍子に、机の上の写しが一枚滑った。"],["セリオン","こちらの束を、寄せても構いませんか。"],["ガレス","ああ。順番はそのままで頼む。"],["","空いた所へセリオンが紙を並べる。リーネは茶碗を自分の方へ寄せた。"],["","紙の隅がリーネの手元へ滑った。彼女が押し戻そうとすると、セリオンがその端を指した。"],["セリオン","少し、そのままで。……こちらの字は？"],["ガレス","原本のままだ。写し手には、読めなかったらしい。"],["","セリオンは字を写した。リーネは筆が離れるのを待ってから、そっと手を引いた。"],["ガレス","原本を見られる者は少ない。写しを増やすにも、許可が要る。"],["ミナト","お前が出せばいい、という話でもないか。"],["ガレス","出せる。明日の会議で、私が説明すればいい。"],["ミナト","何を言われるか、分かってるだろ。"],["ガレス","だから、今まで机の中にあった。"],["","ガレスが空の皿を端へ寄せた。冊子を置く場所が、少し広くなった。"],["ガレス","持っていけ。ここの分は、また作らせる。"],["","冊子へ伸ばした俺の手に、リーネの視線がついてきた。"]],null,[{"text": "人々へ記録を開示する覚悟を尋ねる", "to": "court-disclose", "rel": {"g": 2}, "fragments": ["record"], "flags": {"disclose": true}}, {"text": "自分たちだけで、記録を持ち出す", "to": "court-private", "rel": {"g": 1}, "fragments": ["record"], "flags": {}}]);
scene("court-disclose","CHAPTER 03","分岐A：記録を開く覚悟を尋ねた場合",[["ミナト", "俺たちだけじゃなく、ほかの国にも見せるつもりはあるか。"], ["ガレス", "このままか。"], ["ミナト", "都合の悪い頁も、抜かずに。"], ["", "ガレスは革表紙を見下ろした。しばらくして、机の上の小さな鐘を鳴らす。"], ["", "戻ってきた書記へ、短く告げた。"], ["ガレス", "明日の議題を一つ増やす。原本の閲覧についてだ。"], ["書記", "……承知しました。"], ["", "書記の目が冊子へ動いた。ガレスは何も隠さず、俺の前へ押した。"], ["ガレス", "旅先で困ったら、人を寄越せ。こちらでも動く。"]],"court-after",null);
scene("court-private","CHAPTER 03","分岐B：自分たちだけで記録を持ち出す場合",[["ミナト", "写しを借りる。まずは、こっちで確かめたい。"], ["ガレス", "分かった。"], ["", "ガレスは表紙を閉じ、幅広の紐で結んだ。"], ["ガレス", "濡らすなよ。元の字まで潰れたら、今度こそ読めなくなる。"], ["ミナト", "気をつける。"], ["", "冊子を袋へしまうと、机の上に四角い空きができた。ガレスはそこへ、次の書類を引き寄せた。"]],"court-after",null);
scene("court-after","CHAPTER 03","王都を出る前に",[["","部屋を出るとき、ガレスは扉までついてきた。"],["ガレス","ユーリの所へも行くのか。"],["ミナト","そのつもりだ。"],["ガレス","……そうか。"],["","言いかけた言葉を飲み込み、ガレスは自分の上着の肩を払った。紙の切れ端が落ちた。"],["ガレス","元気でいると、伝えてくれ。"],["ミナト","自分で会いに行けよ。"],["ガレス","会えるなら、そうしている。"],["","ガレスが、セリオンへ目を向けた。"],["ガレス","手間をかけていないか。"],["セリオン","いえ。頼まれたことより、私の用事が増えました。"],["ミナト","……何を頼んだんだ。"],["","俺が聞くと、ガレスは少し眉を寄せた。"],["ガレス","お前が来たら、話を聞いてやってくれとな。"],["セリオン","聞いてもらってるのは、私の方ですが。"],["","ガレスは俺を見てから、彼へ小さく頷いた。"],["","部屋の奥で、書記が新しい書類の束を抱えて待っていた。"],["","俺は頷いて廊下へ出た。"],["","扉の外で、ティアが待っていた。槍を持った兵と話している。"],["ティア","お、終わったか。なあ、南へ行こうぜ。"],["ミナト","……いきなり何だ。"],["ティア","あっちの砦、腕の立つ奴が集まるんだってさ。今、聞いた。見に行こう。"],["ミナト","次は西だ。人に会う。"],["ティア","また話を聞くだけかよ。こっちの方が面白そうだろ。"],["","兵が咳払いをした。ティアは気にせず、俺の返事を待っている。"],["ミナト","西の用が済んだらな。南へ抜ける道もある。"],["ティア","言ったな。じゃあ、そうしよう。"],["","俺が歩き出すより先に、ティアが階段へ向かった。"],["","リーネは手すりへ指を添えたまま、二段ほど下から俺を見上げた。"],["リーネ","……長いお付き合いなんですか。"],["ミナト","ああ。ずいぶんな。"],["リーネ","ミナトさんも、ああいう所でお仕事を？"],["ミナト","いや。勤めたことはない。"],["リーネ","……そう、なんですね。"],["","階段の下から、人が上がってきた。俺は壁へ寄り、三人を先に通した。"],["ミナト","あいつが偉くなる前からの知り合いだ。"],["","リーネは頷いた。廊下の兵と俺の顔を見比べ、何か言いかけて口を閉じた。"],["","少し離れた所で、セリオンが冊子を袋へしまっていた。目が合うと、手を止めた。"],["セリオン","この先でも、ほかの写しと比べられるのですね。"],["ミナト","ああ。会いに行く。"],["セリオン","では、先ほどの字は空けておきます。"],["","彼は手帳を開き直さず、ティアの後を歩いた。"]],"border-road",null);
scene("border-road","CHAPTER 03","峠の向こう",[["","王都を離れると、道は細くなった。"],["","二日目には宿がなくなり、三日目には石畳も途切れた。雨のあとは、靴の裏から土が離れなかった。"],["ティア","本当にこっちなのか。"],["ミナト","もう少しだ。"],["ティア","それ、さっきも聞いたぞ。"],["セリオン","私も二度ほど。"],["","リーネが笑いかけて、足を止めた。木々の間に、赤い布が見える。"],["","枝に結ばれた細い布が、その先にもあった。道しるべらしい。雨に濡れて、どれも同じ方へ垂れている。"],["","細い流れが、道を横切っていた。踏み石へ足を置くと、泥の下で石が傾いた。"],["","俺は岸へ膝をついた。肩から滑った鞄をつかみ損ねる。"],["","ティアが片足を伸ばし、鞄の紐を靴先へ引っかける。"],["ティア","危ねえな。紙まで泳がせる気か？"],["ミナト","助かった。"],["","鞄を受け取ると、底が少し濡れていた。留め具を外す横で、ティアが俺の顔を覗き込んだ。"],["ティア","闘技場の分、これで返したぞ。"],["ミナト","ああ。"],["ティア","よし。"],["","ティアは流れを飛び越え、向こう岸へ立った。リーネが踏み石を確かめていると、手を伸ばす。"],["ティア","そこ、動くぞ。こっち。"],["","渡り終えたリーネが礼を言った。ティアはもう次の曲がり角を見ていた。"],["ティア","で、どっちだ？"],["","俺は鞄を閉じ、布の続く方を指した。"],["ミナト","あった。"],["","枝を避けると、低い屋根が見えた。窓辺に薪が積まれ、軒先では草の束が揺れていた。"],["ティア","煙、出てる。誰かいるぞ。"],["","俺が戸を叩く前に、中から足音がした。"]],"border",null);
scene("border","CHAPTER 03","四つの茶碗",[["ユーリ","……ミナト？"],["","戸を開けたユーリは、赤い帽子の下から俺の顔を見たまま動かなかった。"],["ミナト","久しぶり。"],["ユーリ","そうね。"],["","俺の肩越しに三人を見つけ、彼女は少し目を丸くした。"],["ユーリ","入って。そこ、雨が落ちてくるから。"],["","棚から茶碗を二つ出しかけ、手が止まる。さらに二つ、取り出した。"],["","小さな食卓へ四つ並べてから、自分の茶碗を持ってきた。"],["ティア","いい匂いだな。"],["ユーリ","飲めるといいけど。少し苦いの。"],["","ティアは湯気へ鼻を近づけ、一口飲んだ。すぐに茶碗を離した。"],["ティア","……熱い。"],["ユーリ","それも、そうね。"],["","ユーリが水差しを置く。ティアは礼を言う代わりに、耳を伏せた。"],["リーネ","リーネです。急に来てしまって、すみません。"],["","ユーリが名を小さく繰り返した。茶を注いでいた手を止め、リーネの顔を見た。"],["リーネ","……何か？"],["ユーリ","ううん。髪、濡れてる。拭くものを持ってくるわね。"],["","椅子の背に、乾いた布が一枚ずつ掛かった。"],["","俺が上着を脱ぐと、ユーリは袖口へ手を伸ばした。"],["ユーリ","まだ着てるの、それ。"],["ミナト","着られるからな。"],["ユーリ","ここの縫い方、違う。"],["","指が、俺の継ぎ当てた所を押さえた。布が少し引きつっている。"],["ミナト","穴は塞がった。"],["ユーリ","……そうね。"],["","笑った口元を見て、俺は上着を椅子へ掛けた。"],["","セリオンが濡れた手帳を袋の奥へ押し込む。リーネは茶碗を両手で包んでいた。"],["ユーリ","まだ、探しているのね。"],["ミナト","……ああ。"],["","薪が爆ぜた。ユーリは火の方を見てから、俺へ向き直った。"],["ユーリ","何か食べる？"],["ミナト","先に、見てほしいものがある。"],["","革の冊子を食卓へ置いた。ユーリは紐をほどかず、留められた封を指でなぞった。"],["ユーリ","ガレス、忙しそうだった？"],["ミナト","飯を抜くくらいには。"],["ユーリ","変わらないのね。"],["ミナト","元気でいるって、伝えてくれとさ。"],["","ユーリは頷いた。しばらくして、棚の奥から平たい箱を持ってきた。"],["","中には紙が詰まっていた。端が擦れたものも、何度も折り直したものもある。"],["ユーリ","こっちは、歌ばかり。"],["セリオン","拝見しても？"],["ユーリ","どうぞ。順番は、あまり当てにしないで。"],["","セリオンが一枚を持ち上げると、裏側から、もっと小さな紙が落ちた。"],["","リーネが拾った。短い節が、繰り返し書かれている。"],["リーネ","これ、知ってます。寝る前に、歌ってもらったことがあります。"],["ユーリ","どんな歌だった？"],["","リーネは少し迷ってから、小さな声で歌った。二度目の節で言葉に詰まる。"],["リーネ","……この先、違ったかもしれません。"],["ユーリ","私の知っているのとは、少し違うわね。"],["","ユーリが続きを口ずさんだ。低い、静かな歌だった。"],["ユーリ","こわいひとも、ゆめをみる。むぎをまいて、あさをまつ。"],["ユーリ","こわいひとにも、まどがある。あけておくれと、かぜがなく。"],["","ティアは空の茶碗へ手を伸ばしかけ、歌が終わるまで待った。セリオンの筆は動いていた。"],["リーネ","私の所では、お花の歌だって聞きました。怖い人は、花を踏まないように歩くんだって。"],["ユーリ","ここでは、災厄の歌だって教わったわ。同じ節なのに、不思議ね。"],["ティア","……それ、どこに置けばいい？"],["","ユーリが振り向くと、ティアは空の茶碗をまとめていた。"],["ユーリ","流しにお願い。ありがとう。"],["ユーリ","この歌を教えてくれた人はね。昔は、おしまいに名前を呼んだんだって。"],["","リーネが自分の知っている節を、小さく口の中で繰り返した。"],["ユーリ","おやすみ、って。でも、誰に言っていたのかは、もう知らなかった。"],["","戻ってきたティアが、リーネの肘のそばへ茶碗を一つ置いた。薄めた茶が入っていた。"],["","俺は箱の中へ目を戻した。似た歌詞が、別の字でも書かれている。"],["ティア","なあ。雨、弱くなったぞ。ちょっと外、見てくる。"],["","戸口まで行ったティアが、軒先で空を見上げた。濡れた土を靴の爪先で掻いている。"],["セリオン","これは、どこで。"],["ユーリ","川沿いの村。下に重なっている紙は、峠の向こうで集めたものよ。獣人の集落にも、似た歌があったわ。"],["","軒先から、ティアが顔を出した。"],["ティア","……あたしの所じゃ、そんな歌、聞かなかったぞ。"],["ユーリ","あなたの育った所では、歌わなかったのかもしれない。"],["","ティアは椅子へ戻り、窓の外を見た。セリオンは紙を二枚並べ、歌の同じ箇所に印をつけた。"],["ユーリ","怖いって、みんな言うの。でも、窓を開けてほしいとも歌う。"],["ミナト","……どっちかだけ、残すわけにはいかないな。"],["","ユーリが頷いた。俺の前へ、一枚ずつ紙を並べていく。"],["ユーリ","災厄にも、名前があった。少なくとも、この歌を残した誰かは、知っていたのよ。"],["","雨が屋根を叩いていた。リーネが押さえている紙だけは、食卓の真ん中に残った。"]],null,[{"text": "各種族に、彼らの名前を届けてほしいと頼む", "to": "border-share", "rel": {"y": 2}, "fragments": ["song"], "flags": {"share": true}}, {"text": "旅に必要な歌だけを写して立ち去る", "to": "border-copy", "rel": {"y": 1}, "fragments": ["song"], "flags": {}}]);
scene("border-share","CHAPTER 03","分岐A：名前を届けてほしいと頼んだ場合",[["ミナト", "この歌、俺たちだけで持っていくんじゃなくて。ほかの土地の人にも、聞いてもらえないか。"], ["ユーリ", "私が？"], ["ミナト", "どこで、誰から聞いたか。俺じゃ分からないことも、お前なら話せる。"], ["", "ユーリは椅子の背へ手を置いた。そこに掛かっている上着を、俺が取ろうとする。"], ["ユーリ", "置いておいて。ほつれ、直すから。"], ["ミナト", "急がなくていい。"], ["ユーリ", "急いでないわ。"], ["", "窓の外を見てから、彼女は紙を一枚引き寄せた。"], ["ユーリ", "まずは、手紙を書いてみる。返事が来るかは、分からないけど。"], ["ミナト", "ああ。頼む。"]],"border-after",null);
scene("border-copy","CHAPTER 03","分岐B：必要な歌だけ写す場合",[["ミナト", "この二つ、写していってもいいか。"], ["ユーリ", "持っていって。写しはあるから。"], ["ミナト", "でも。"], ["ユーリ", "雨で濡らさないでね。"], ["", "彼女は油を引いた布を持ってきた。紙を包む手つきに迷いがない。"], ["", "俺は包みを受け取った。ユーリの手が離れてから、礼を言った。"]],"border-after",null);
scene("border-after","CHAPTER 03","雨のあとの道",[["", "雨が上がっても、ユーリはすぐに戸を開けなかった。"], ["ユーリ", "もう少し待って。上の枝から、まだ落ちてくるから。"], ["", "ティアが戸口で足踏みをする。ユーリが渡した袋から、焼いた木の実の匂いがした。"], ["ティア", "これ、いくらだ。"], ["ユーリ", "いいの。旅で食べて。"], ["ティア", "それじゃ借りになるだろ。"], ["ユーリ", "じゃあ、次に来るとき。あなたの好きなものを教えて。"], ["", "ティアは袋を持ち直した。"], ["ティア", "……分かった。覚えとけよ。"], ["ユーリ", "ええ。"], ["", "セリオンが先に出た。リーネは戸の前で頭を下げ、濡れた段を一つずつ下りた。"], ["", "ユーリが、俺の上着の襟を直した。"], ["ユーリ", "無茶しないで。"], ["ミナト", "お前もな。"], ["", "指が離れた。俺は何か言おうとして、結局、鞄を背負い直した。"], ["", "少し歩いて振り返ると、まだ戸が開いていた。赤い帽子が、小さく揺れる。"], ["", "曲がり角で家が見えなくなった。"], ["リーネ", "……優しい方ですね。"], ["ミナト", "そうだな。"], ["", "リーネは何か続けかけ、足元の水たまりを避けた。"], ["", "少し先で、ティアが袋を開けている。セリオンにも一つ差し出した。"], ["ティア", "ほら。歩きながらそればっか見てると、転ぶぞ。"], ["", "セリオンは筆をしまった。空いた手で受け取ってから、来た道を一度見た。"], ["", "木々から落ちる雫が、まだ背中で鳴っていた。"]],"races-road",null);
scene("races-road","CHAPTER 04","約束した寄り道",[["","山道が二つに分かれた所で、ティアが道しるべを叩いた。"],["ティア","南は、こっちだ。"],["ミナト","分かってる。"],["ティア","念のためだよ。あんた、すぐ紙のある方へ行くからな。"],["","道しるべの根元に、折れた矢が供えてあった。リーネは踏まないよう、少し離れて歩いた。"],["","砦は谷の向こうにあった。城壁の上には、人間の兵と獣人の兵が立っている。"],["","広場で木剣の音がした。ティアの耳が、そちらを向いた。"],["ティア","お。やってる。"],["ミナト","先に泊まる所を――。"],["","もう聞いていなかった。人の間をすり抜け、木剣を振っている兵の前へ立つ。"],["ティア","あたしも混ぜろ。"],["古参の兵","見物か？　なら、あっちから見てな。"],["ティア","見物じゃない。やる方だ。"],["","古参の兵は手を止め、ティアの顔を見た。もう包帯の取れた掌へ、木剣を一本放る。"],["古参の兵","三本。顔と喉はなしだ。始める前に、荷物を下ろせ。"],["","ティアが鞄を俺へ押しつけた。"],["ミナト","おい。"],["ティア","持ってろ。すぐ戻る。"],["","最初の一本は、早かった。踏み込んだティアの剣を兵が流し、胸元で止めた。"],["ティア","……今の、もう一回。"],["古参の兵","あと二本ある。"],["","二本目は、砂埃で足元が見えなくなった。ティアが懐へ潜り、兵の脇へ木剣を当てる。"],["","見物していた若い兵が声を上げた。古参の兵は笑い、立つ位置を変えた。"],["","三本目。ティアの剣が兵の肩へ触れるより先に、足が払われた。"],["","背中が土へ落ちた。リーネが駆け寄りかけ、足を止める。"],["","ティアは横になったまま、兵の足を見ていた。"],["古参の兵","これで終わりだ。"],["ティア","待て。今の足、どうやった。"],["ミナト","三本って言われただろ。"],["ティア","見せてもらうだけだ！"],["","兵が差し出した手を取って、ティアは跳ね起きた。背中についた土を払う気もないらしい。"]],"races-yard",null);
scene("races-yard","CHAPTER 04","待っている人たち",[["", "広場の外で、リーネが石垣に腰を下ろした。"], ["リーネ", "……止めなくて、いいんですか。"], ["ミナト", "どっちの話だ。"], ["リーネ", "また、もう一回って。"], ["", "古参の兵は木剣を持たずに構えた。ティアが同じように足を置き、何か言っている。"], ["ミナト", "今は、大丈夫そうだ。"], ["", "リーネは頷いた。"], ["リーネ", "次の町には、冒険者の宿、ありますか。"], ["ミナト", "ある。ここにも、あるはずだ。"], ["リーネ", "兄のこと、聞いてみようと思って。"], ["", "広場で笑い声がした。ティアが兵へ言い返している。"], ["ミナト", "……そうか。"], ["リーネ", "ここまで来たら、知っている人がいるかもしれませんし。"], ["", "俺は広場から目を離した。"], ["ミナト", "今日、寄ってみるか。"], ["", "リーネが顔を上げた。"], ["リーネ", "……はい。"], ["", "少し向こうでは、セリオンが石垣に刻まれた文字を写していた。"], ["", "砦の修理に使われた石らしい。文字の途中へ、新しい鉄の杭が打ち込まれていた。"], ["セリオン", "こちらの石は、どこから運ばれたのでしょう。"], ["砦の兵", "川向こうの旧道だ。道を広げた時、余った石を持ってきた。"], ["セリオン", "川向こうにも、読めるものは残っていますか。"], ["砦の兵", "さあな。渡れるなら、見てくればいい。"], ["", "川の先へ、黒い柱が二本立っていた。間にあるはずの橋が、途中で途切れている。"], ["", "戻ってきたティアの背中は、土で白くなっていた。"], ["ティア", "見たか、最後の足。あそこから崩せるんだぞ。"], ["ミナト", "見てた。"], ["ティア", "次なら、避けられる。"], ["", "リーネが水筒を差し出した。ティアは受け取り、一息に飲みかけて肩を止めた。"], ["リーネ", "……背中、擦りましたか。"], ["ティア", "ちょっとな。"], ["", "リーネが布を濡らす。ティアはそれを見てから、広場を振り返った。古参の兵は、別の相手と木剣を合わせている。"], ["ティア", "まだやってるぞ。"], ["リーネ", "終わったら、見に行きましょう。"], ["", "ティアは少し迷い、リーネの前へしゃがんだ。"], ["", "布が触れると、耳がぴくりと動いた。"], ["リーネ", "痛いですか。"], ["ティア", "冷たい。"], ["リーネ", "では、痛くはないんですね。"], ["ティア", "……ちょっとだ。"], ["", "リーネは傷の周りから、ゆっくり土を拭った。ティアの指が水筒の蓋を回している。"], ["ティア", "半分、残した。あんたも飲めよ。"], ["リーネ", "ありがとうございます。"], ["", "手当てが済むと、ティアは立ち上がり、今度はリーネが布をしまうのを待った。"], ["ティア", "なあ、ミナト。次も、こういう所へ行くのか？"], ["ミナト", "強い奴がいるかは、知らないぞ。"], ["ティア", "そっちは、あたしが探す。"], ["", "リーネが鞄を閉じると、ティアはその隣から広場を見やった。"]],"races",null);
scene("races","CHAPTER 04","向こう岸の声",[["", "宿の食堂には、橋のことを書いた紙が貼ってあった。"], ["", "川向こうへの荷は預かれない、とある。釘の下に、新しい紙が何枚も重ねられていた。"], ["宿の主人", "先月から、あのままだ。うちへ言われても困る。"], ["ミナト", "壊れたままなのか。"], ["宿の主人", "外したんだ。向こうがな。"], ["", "食卓の端で、荷運びの男が顔を上げた。背中に畳んだ羽が、椅子へ当たっている。"], ["荷運びの男", "先に兵を増やしたのは、こっちだろ。"], ["宿の主人", "こっちじゃない。砦へ言ってくれ。"], ["荷運びの男", "砦へ行けば、橋を戻せって言われる。俺は金具を運んでただけなんだぞ。"], ["", "男が卓の下を蹴った。木箱から、鈍い金属音がした。"], ["", "ティアが椀から顔を上げる。"], ["ティア", "じゃあ、渡すものは、ここにあるんだろ。"], ["荷運びの男", "あるよ。受け取る奴が来ない。"], ["ティア", "呼べばいいじゃないか。"], ["", "男は口を開きかけた。窓の外を一度見てから、椀へ目を戻す。"], ["荷運びの男", "俺が呼べば、向こうと通じてるって言う奴がいる。"], ["", "食堂が静かになった。少し離れた席で、砦の腕章をつけた男が匙を置いた。"], ["", "リーネは俺を見た。何か聞きたそうにしていたが、その席の男を見て目を伏せる。"], ["ティア", "……面倒くさいな。"], ["ミナト", "ティア。"], ["ティア", "分かってるよ。殴ればいい話じゃないってくらい。"], ["", "荷運びの男は、少しだけ笑った。"], ["", "食事が終わりかけた頃、セリオンが写した文字を俺へ見せた。"], ["セリオン", "石は、死者を悼んで立てられたもののようです。続きは、向こう岸に。"], ["ミナト", "ガレスの記録と、つながりそうか。"], ["セリオン", "同じ語があります。ただ、石を見ないうちは。"], ["", "俺は紙の文字を見た。荷運びの男が、椀を下げている。"], ["セリオン", "無理に渡る必要はありません。ほかの道を探すこともできます。"], ["", "返事を急かさず、セリオンは紙を畳んだ。"], ["", "荷運びの男が木箱へ手を掛けた。持ち上がらず、一度床へ戻す。"], ["", "俺は箱の反対側へ手を伸ばした。"]],null,[{"text": "皆が話せる場をつくり、互いの恐れを聞く", "to": "races-talk", "rel": {"r": 3, "l": 1, "s": 1}, "fragments": ["stone"], "flags": {"council": true}}, {"text": "共通の敵がいれば争わずに済むと説く", "to": "races-enemy", "rel": {}, "fragments": ["stone"], "flags": {}}]);
scene("races-talk","CHAPTER 04","分岐A：双方の話を聞く場をつくる",[["ミナト", "ここまで運んだんだ。受け取るかどうかだけでも、聞いてみないか。"], ["荷運びの男", "向こうへ渡す当てでもあるのか。"], ["ミナト", "当てはない。だから、砦にも話す。"], ["", "男は俺の手を見た。しばらくして、箱から手を離す。"], ["荷運びの男", "勝手に、俺が何か約束したことにはするなよ。"], ["ミナト", "ああ。"], ["", "古参の兵を見つけると、ティアが先に手を上げた。"], ["ティア", "さっきの続きじゃないぞ。今度は、こいつの用だ。"], ["ミナト", "橋のことで、人を一人出してほしい。"], ["古参の兵", "俺に決められる話じゃない。"], ["ミナト", "決められる奴に会いたい。"], ["", "話を取り次いでもらうだけで、その日は終わった。"], ["", "翌朝、砦の担当者が宿へ来た。川向こうへの伝言を引き受けたのは、荷運びの男だった。"], ["", "返事が戻ったのは、さらに二日後だ。"], ["", "川辺には、向こう岸からの小舟が一艘来た。橋はまだ、外されたままだった。"], ["", "砦の担当者は岸の杭へ手を置き、鳥人の使いは舟から降りなかった。"], ["鳥人の使い", "荷だけだ。兵は渡さない。"], ["砦の担当者", "こちらも、橋を戻すまで増員は下げられん。"], ["", "また同じ所へ戻りかけた。荷運びの男が、木箱の蓋を開ける。"], ["荷運びの男", "それを決める前に、こいつを受け取るかだけ、言ってくれ。"], ["", "金具が日に光った。使いの一人が舟から身を乗り出す。"], ["", "話が終わった頃、木箱は舟へ移っていた。約束できたのは、三日後にもう一度会うことだけだった。"], ["", "セリオンは石碑を見る許しを得た。俺は箱を下ろした跡の、泥の窪みを見ていた。"]],"races-stone",null);
scene("races-enemy","CHAPTER 04","分岐B：共通の敵がいれば争わずに済むと説く",[["ミナト", "災厄がいるうちは、橋一本で争ってる場合じゃないだろ。"], ["宿の主人", "だから、兵が要るんじゃないのか。"], ["荷運びの男", "だから橋を外したんだって、向こうも言うよ。"], ["", "返す言葉が、すぐには出なかった。"], ["", "荷運びの男は箱へ腰を下ろした。俺が反対側を持ち上げかけていたので、慌てて下ろす。"], ["荷運びの男", "……石を見たいんだろ。荷を引き上げる舟が、明日来る。聞くだけは、聞いてやる。"], ["ミナト", "いいのか。"], ["荷運びの男", "箱を運んでくれようとしただろ。それくらいならな。"], ["", "翌日、俺たちは荷の戻る舟に乗せてもらった。橋も、金具の入った箱も、前の日のままだった。"]],"races-stone",null);
scene("races-stone","CHAPTER 04","消えた名を写す",[["", "死者を悼んで立てられた石碑は、川から離れた斜面にあった。"], ["", "石の前には、風で乾いた花が供えてある。セリオンが膝をつき、苔を指で避けた。"], ["", "ティアは周りを一回りしてから、俺の隣へ戻ってきた。"], ["ティア", "何が書いてある。"], ["ティア", "何が分かった。こいつを残したのは、どんな奴だ？"], ["ティア", "短く教えろよ。さっきの話みたいに、何日も待つのはごめんだぞ。"], ["", "セリオンが振り返った。ティアは目を逸らさずに待っている。"], ["セリオン", "誰かを弔った言葉です。その人のそばにいた人が、次に恐れられるようになった、と。"], ["ティア", "災厄にやられたってことか？"], ["セリオン", "そうとも読めます。ただ、王都の記録にも似た箇所がありました。"], ["", "セリオンは二つの写しを出した。片方を石へ、もう片方を膝へ置く。"], ["セリオン", "同じような話が、別の土地にもあります。近くにいた者へ、何かが移ったように。"], ["ミナト", "……近い者へ。"], ["セリオン", "ええ。ただし、距離のことか、間柄のことかも分かりません。"], ["", "風が紙をめくった。セリオンは押さえ直した。"], ["セリオン", "その後の争いが少なかったという記録もあります。たまたま残っただけかもしれませんが。"], ["ティア", "そばにいたせいか、次に狙われる理由が別にあったのか。そこは、まだ分からないんだな。"], ["セリオン", "はい。"], ["ティア", "分かった。じゃあ、そいつが何をしたのかも探さないとな。"], ["セリオン", "ええ。そこを読み飛ばすわけにはいきません。"], ["", "ティアは何か言いかけ、鼻を鳴らした。"], ["", "リーネが、乾いた花を石の前へ戻した。写しを取る邪魔にならない所に、そっと置く。"], ["リーネ", "お名前は、残ってないんですか。"], ["", "セリオンは字を追った。それから、ゆっくり首を振った。"], ["", "リーネは石を見上げた。誰に向ければいいのか迷うように、手を合わせた。"]],"neia-road",null);
scene("neia-road","CHAPTER 04","霧の道",[["", "川を離れて二日目、道に霧が出た。"], ["", "先を歩くティアの尾が、白い中へ消えかける。"], ["ミナト", "離れるな。"], ["ティア", "分かってる。"], ["", "言い終えるより先に、ティアが止まった。"], ["", "低い音がした。枝が折れたのではない。石を何か硬いものが擦っている。"], ["", "ティアの手が武器へ伸びた。俺はその腕を押さえた。"], ["ティア", "おい。"], ["", "霧の中に、二本の角が見えた。"], ["", "大きな肩が道を塞いでいる。朱色の布の下で、白い鱗がゆっくり上下していた。"], ["", "リーネが息を呑んだ。俺は半歩前へ出た。"], ["ネイア", "……また、人を連れているのか。"]],"neia",null);
scene("neia","CHAPTER 04","忘れられない証人",[["","ネイアの剣は、もう鞘から抜かれていた。切っ先が、俺の胸より少し下を向く。"],["ティア","誰だ。"],["ミナト","下がってろ。"],["ティア","あたしに言うな。あっちに聞いてる。"],["","ネイアはティアを見なかった。"],["ネイア","ヴァルゼンの名を、覚えているか。"],["","霧の中に、記憶の光景が重なった。石の床。倒れた大きな影。"],["ミナト","……覚えてる。"],["ネイア","言え。"],["","ティアが俺を見た。"],["ミナト","ヴァルゼン。"],["","切っ先が、少しだけ下がった。"],["ネイア","お前が殺した。"],["","俺は頷いた。"],["ティア","……魔王、のことか。"],["","ネイアの目が、初めてティアへ向いた。ティアが足を開く。"],["ミナト","俺に話せ。"],["ネイア","その呼び方なら、みんな覚えている。"],["","剣を握る指が鳴った。ネイアは俺へ目を戻した。"],["ネイア","声が、思い出せない。"],["","返事はできなかった。"],["ネイア","怒鳴った声なら、まだある。だが、そうではない時の声が……。"],["","大きな口が閉じた。息で、白い胸の鱗が揺れた。"],["ネイア","いつも、あんな声だったわけではない。"],["","誰も動かなかった。セリオンも、袋へ手を伸ばさなかった。"],["ネイア","お前は、忘れないのか。"],["ミナト","……ああ。"],["ネイア","なぜだ。"],["","俺は答えず、腰の剣へ手を置いた。ティアの肩に力が入る。"]],null,[{"text": "剣を置き、その人の暮らしを聞く", "to": "neia-listen", "rel": {"n": 2, "r": 1}, "fragments": ["witness"], "flags": {}}, {"text": "討伐は必要だったと答える", "to": "neia-defend", "rel": {}, "fragments": ["witness"], "flags": {}}]);
scene("neia-listen","CHAPTER 04","分岐A：剣を置き、その人の暮らしを聞く",[["","剣を帯から外した。鞘ごと、足元の石へ置く。"],["ティア","ミナト。"],["","俺は手のひらを見せた。ネイアの剣は、まだこちらを向いていた。"],["ミナト","どんな声だった。"],["ネイア","……何だと。"],["ミナト","思い出せる所だけでいい。聞かせてくれ。"],["","ネイアは俺を見下ろした。ずいぶん長い間、そうしていた。"],["ネイア","朝に、戸を開けるのを嫌がった。外から見えると言って。"],["ネイア","だが、鉢を置くなら日が要る。毎日、少しだけ開けた。"],["","鉢。あの戦いの後、床に土が散っていたのを覚えている。"],["","俺は目を閉じかけ、開いたままネイアを見た。"],["ネイア","芽が出た時……何を言ったのだったか。"],["","言葉が止まった。風でマントの裾が動いた。"],["ミナト","……急がなくていい。"],["","ネイアの顎が強張った。"],["","しばらくして、俺は足元の剣を拾い、鞘ごと帯へ戻した。"],["ネイア","お前に、それを言われたくはない。"],["ミナト","……そうだな。"],["","剣先が下がった。許されたわけではなかった。俺は足元の剣を拾わずに待った。"]],"neia-after",null);
scene("neia-defend","CHAPTER 04","分岐B：討伐は必要だったと答える",[["ミナト", "……あの時は、止めるしかなかった。"], ["ネイア", "誰も、ほかの言い方をしない。"], ["", "ネイアが一歩寄った。俺は剣を抜かなかったが、柄から手も離せなかった。"], ["ネイア", "必要だった。仕方なかった。それで、何を覚えている。"], ["ミナト", "……。"], ["ネイア", "私は、鉢を窓へ寄せる手を覚えている。芽が出るまで、毎日動かしていた。"], ["ネイア", "お前が片づけた場所には、そういうものもあった。"], ["", "ティアが一歩踏み出しかけた。俺は手で止めた。"], ["", "ネイアはもう近づかなかった。剣を下げ、俺から顔を背けた。"]],"neia-after",null);
scene("neia-after","CHAPTER 04","残された紙",[["","ネイアが布包みを地面へ置いた。"],["ネイア","書いておいた。思い出せなくなる前に。"],["ミナト","……俺が、持っていていいのか。"],["ネイア","お前が忘れないなら、持っていろ。"],["","包みの結び目には、細い金属の輪が通してあった。角の根元にも、同じ模様がある。"],["ネイア","殺した相手のことだ。知っておけ。"],["","霧の中へ、大きな肩が消えた。足音が聞こえなくなってから、俺は腰の剣を確かめ、包みを拾った。"],["ティア","追うのか。"],["ミナト","いや。"],["ティア","……そうか。"],["","ティアは、リーネのすぐ前に立ったままだった。相手が去っても、しばらく足を動かさなかった。"],["","セリオンが俺の手を見た。"],["セリオン","お持ちしましょうか。"],["ミナト","大丈夫だ。"],["","セリオンは頷いた。包みを開けて見せろとは言わなかった。"],["","歩き出すと、リーネが少し遅れてついてきた。"],["リーネ","……ミナトさん。"],["","振り返ると、言葉を探している顔だった。"],["ミナト","さっきのことか。"],["","リーネは頷いた。"],["ミナト","俺が殺した。それは、本当だ。"],["","リーネの目が下がった。俺の腰から、手元の包みへ。"],["リーネ","……はい。"],["","それからしばらく、誰も話さなかった。"],["","道が狭くなる所で、ティアが振り返った。"],["ティア","あたしが先に行く。変な奴がいたら、今度は先に言えよ。"],["ミナト","分かった。"],["","ティアはそれだけ確かめると、前へ向き直った。"],["","霧の中で、リーネの靴音が続いていた。俺は速さを落とし、その音が近づくのを待った。"]],"prayer-inn",null);
scene("prayer-inn","CHAPTER 05","まだ聞いていないこと",[["", "宿の主人は、カイルという名を三度聞き返した。"], ["リーネ", "栗色の髪で、目は緑です。年は、ミナトさんと同じくらいかと……。"], ["宿の主人", "似た奴なら、いくらでも来るからなあ。"], ["", "リーネは頷いた。礼を言って戻ってくると、食卓の端へ腰を下ろした。"], ["ティア", "どうだった。"], ["リーネ", "分からないそうです。"], ["ティア", "ふうん。じゃ、次だな。"], ["", "リーネは鞄を膝へ引き寄せた。返事がなかったので、ティアもその先は言わなかった。"], ["", "俺は布包みを開いた。ネイアが残した紙には、筆を止めた跡がいくつもあった。"], ["", "鉢に水をやる量。戸を開ける時刻。何を話したか思い出せず、空けてある行。"], ["", "ヴァルゼンの名だけは、何度も書かれていた。"], ["リーネ", "……あの方の、ですか。"], ["ミナト", "ああ。"], ["", "リーネは覗き込まず、俺が持つ紙を見ていた。"], ["ミナト", "見てもいい。"], ["", "彼女は一枚を受け取った。読み終えても、すぐには返さなかった。"], ["リーネ", "お水、毎日やると、根が腐るものもあるんです。"], ["", "俺は顔を上げた。"], ["リーネ", "ここ。少ししかやらなかったって、怒っています。でも、たぶん……それでよかったんだと思います。"], ["", "紙へ目を戻した。あの大きな手で、小さな鉢の土を確かめていた。"], ["ミナト", "……そうか。"], ["", "リーネは紙を両手で戻した。"], ["リーネ", "私が教えてもらった話には、こういうこと、何も出てきませんでした。"], ["ミナト", "俺も、聞かなかった。"], ["", "リーネが俺を見た。言いかけて、一度唇を閉じる。"], ["リーネ", "ミナトさんは、倒す前に、その人と話したんですか。"], ["", "隣で、ティアが匙を置いた。俺は紙の端を押さえた。"], ["ミナト", "……少しは。"], ["リーネ", "それでも、知らなかったんですね。"], ["", "責める声ではなかった。俺は頷くしかなかった。"], ["", "セリオンは何も尋ねず、写し終えた一枚を俺の横へ置いた。"]],"prayer-weeks",null);
scene("prayer-weeks","CHAPTER 05","行って、戻って",[["","それからの旅は、同じ道を何度も行き来した。"],["","橋のある川辺へ戻ると、渡しの時刻を書いた板が立っていた。橋の材木は、まだ岸に積まれている。"],["","別の町では、俺たちが届けた手紙を封も切らずに返された。次の町では、返事を待つ間に雨の季節が終わった。"],["ティア","なあ。ここの道、もう覚えたぞ。"],["ミナト","俺もだ。"],["ティア","そういうことじゃない。"],["","荷車の脇を歩きながら、ティアが俺の地図を引いた。"],["ティア","次、こっちを通れ。尾根の方だ。"],["ミナト","遠回りになる。"],["ティア","距離ならな。下は昨日、馬車が埋まってた。あたしたちまで押す羽目になるぞ。"],["","地図から目を上げた。谷へ下りる道には、車輪の深い跡が続いていた。"],["ミナト","……分かった。"],["ティア","だろ。"],["","尾根の道は風が強かったが、靴は泥に取られなかった。"],["","途中で、リーネが鞄の底を確かめた。薬の残りを数え、次の村で何を買うか小さな紙へ書いている。"],["セリオン","それは、私が持ちましょう。"],["リーネ","軽いものですから。"],["セリオン","先ほどから、右肩に掛けた鞄を何度も持ち直しています。"],["","リーネは一度迷い、小瓶を二本差し出した。セリオンは手帳とは別の袋へ入れた。"],["","夜は、手紙を待つ日が増えた。"],["","俺が宿の入口を見ていると、ティアが床に木片を置いた。"],["ティア","暇なら、付き合え。"],["ミナト","何だ、これ。"],["ティア","向こうの宿で教わった。先に相手の駒を囲んだ方が勝ちだ。"],["","最初の二局は、俺が負けた。ティアは、俺が置く前から次の木片を指へ挟んで待っていた。"],["","三局目、俺が端へ駒を寄せると、ティアの手が止まった。"],["ティア","……そっちは、誘いか。"],["ミナト","どうだろうな。"],["","ティアは俺の駒ではなく、残った空きを数えた。それから別の所へ置いた。"],["","リーネが向かいの椅子へ座った。セリオンも筆を休める。"],["","勝負が終わる頃、入口に使いの者が立っていた。"]],"prayer-compare",null);
scene("prayer-compare","CHAPTER 05","返事を書く場所",[["", "ガレスから届いた紙には、今も各地で行われている祈りの手順が書かれていた。"], ["", "ユーリの古い歌の写しを横へ置くと、セリオンが二つの箇所を指で押さえた。"], ["セリオン", "こちらは、神へ願いを述べる言葉です。次が、その返事を待つ間。"], ["ミナト", "今は、そこを空けないのか。"], ["セリオン", "すぐに次の祈りへ移っています。歌の方には、もう一節あるのですが。"], ["", "リーネは紙を受け取り、口の中で節を確かめた。"], ["リーネ", "ここで止まると、歌いにくいです。前の言葉と、次の言葉がつながらなくて。"], ["セリオン", "間に一節あった、というのは間違いなさそうですね。"], ["リーネ", "何と歌っていたかまでは、分かりません。"], ["セリオン", "ええ。それは、まだ。"], ["", "紙の隅に、祈りに使う石の絵があった。中央だけが、彫られずに残っている。"], ["ミナト", "これを、見に行きたい。"], ["", "セリオンは絵を見た。それから、俺へ顔を向けた。"], ["セリオン", "調べるだけですか。"], ["ミナト", "まずは。"], ["セリオン", "何か試すなら、その前に声をかけてください。私も、読めていない所があります。"], ["", "俺は頷いた。セリオンはそれ以上聞かず、紙を巻いた。"]],"prayer-method",null);
scene("prayer-method","CHAPTER 05","冊子の最後の紙",[["","セリオンがガレスの冊子から、細く折られた紙を抜いた。"],["","紙には、刻印の形がいくつも写されていた。線のつなぎ方を説明する文字が、隅に添えてある。"],["セリオン","こちらも、確かめたいのです。力を封じたものを、解く手順のようですが。"],["ミナト","解いたら、どうなる。"],["セリオン","この写しには、ありません。最後の紙が欠けています。"],["ミナト","別の所なら、続きがあるかもしれないな。"],["","セリオンは頷いた。読めた線へ印をつけ、読めない所は空けておいた。"],["","その後の旅で、似た線を何度か見つけた。封じられた倉や、使われなくなった祈りの道具に。"],["","一つずつ写し、土地の者に使い方を聞いた。合う所も、合わない所もあった。"],["セリオン","同じ形に見えても、つないだものが違います。写しだけで試すのは、危険です。"],["","俺は、彼の空けた箇所を見ていた。"]],"prayer-stone",null);
scene("prayer-stone","CHAPTER 05","石の余白",[["","古い祈りの場には、落ち葉が積もっていた。石の縁を払うと、浅い溝がいくつも現れた。"],["","セリオンが膝をついた。リーネは枝を拾い、溜まった水を流した。"],["ティア","これ、割れてるわけじゃないんだな。"],["ミナト","溝のことか。"],["ティア","ああ。全部、真ん中へ向いてる。"],["","石の中央だけは平らだった。彫り損ねたのではなく、そこへ何かを置くための形に見える。"],["セリオン","名前を書く場所だったようです。神の名と、祈る側の名を。"],["ミナト","一人分じゃないな。"],["セリオン","ええ。溝の端にも、それぞれあります。"],["","ティアが一歩引いて石を見た。爪先で落ち葉を避け、隠れた溝をもう一本見つける。"],["ティア","ここにも。全部出さないと、形を間違えるぞ。"],["","日が傾く頃には、石の周りを一周できるようになった。中央は、この世界の神アウレへ名を告げる場所だという。"],["リーネ","アウレ様に、お名前をお伝えする場所なんですね。"],["セリオン","少なくとも、そう使われていたようです。"],["ミナト","今も、使えると思うか。"],["","セリオンは字を読み直した。長い間、筆を持ったままだった。"],["セリオン","分かりません。祈りが届くことと、返事があることは、同じではありませんから。"],["ティア","試した奴は？"],["セリオン","記録には、見つかりませんでした。"],["ティア","じゃあ、今度はちゃんと書いとけよ。次の奴が困らないように。"],["","セリオンが小さく笑った。"],["セリオン","そのつもりです。"]],"prayer-night",null);
scene("prayer-night","CHAPTER 05","眠らない夜",[["","祈りの場の外で火を起こした。焚き火の明かりが、石まで届く。"],["","手紙の返事には、話し合いの場に来られる者と、来られない者の名があった。まだ返事のない土地もある。"],["","俺はそれを畳み、袋の奥へしまった。"],["","ティアが横になった。背を向けたまま、片手を上げる。"],["ティア","夜中に一人で歩くなら、言えよ。見張りが面倒になる。"],["ミナト","……起きてたのか。"],["ティア","足音が変わった。"],["","俺は火のそばへ戻った。ティアは目を閉じたままだった。"],["","焚き火が小さくなった頃、俺はもう一度、石へ目を向けた。"]],null,[{"text": "古い祭儀を照合し、各種族の返答を石に刻む", "to": "prayer-contact", "rel": {"r": 1}, "fragments": ["contact"], "flags": {"contact": true}}, {"text": "仲間のもとへ戻り、明日の話をする", "to": "prayer-return", "rel": {"l": 1, "t": 1}, "fragments": [], "flags": {}}]);
scene("prayer-contact","CHAPTER 05","分岐A：古い祭儀を照合し、各種族の返答を石に刻む",[["","ティアへ声をかけて、石へ戻った。彼女は起き上がり、火に薪を足した。"],["","セリオンが写した手順を開く。各地から持ち帰った返事を、石の縁へ並べた。"],["","人間の祈りと、古い歌。石に刻まれた文字に残った言葉。ネイアが、あの紙へ記した名。"],["","それぞれの言葉を、石のどこへ置くかが見えてきた。"],["","俺は文字を彫るための細い鉄の棒を石へ当てた。一文字ずつ、返事を刻んでいく。"],["","誰かが来る音はしなかった。石も、光らなかった。"],["","最後の文字から手を離すと、夜風が紙の端を持ち上げた。"],["","焚き火へ戻る。ティアが俺の席を足で押し、少しだけ空けた。"],["ティア","終わったのか。"],["ミナト","ああ。"],["ティア","じゃ、寝ろ。次、あんたの番だからな。"]],"prayer-send",null);
scene("prayer-send","CHAPTER 05","持っていく返事",[["", "夜が明けてから、石の写しを取った。刻んだものと同じ内容を、手紙にも書いた。"], ["", "神へ何を願い、その後で自分たちは何を引き受けるか。返事をくれた者の名を、もう一度確かめる。"], ["セリオン", "伝わったかどうかを、こちらで決めるわけにはいきませんね。"], ["ミナト", "ああ。違っていたら、直してもらう。"], ["", "町へ戻り、使いを頼んだ。返事の来る間も、旅は続いた。"], ["", "届いた紙には、書き直された言葉もあった。自分の名だけを書いたものも、条件を長く連ねたものもある。"], ["", "俺はどれも捨てず、石の写しへ挟んだ。"]],"@six",null);
scene("prayer-six","CHAPTER 05","六つの返事",[["", "最後の包みには、ネイアの金属の輪と同じ模様が刻まれていた。"], ["", "魔族の言葉が、二行。セリオンが字を追い、読む順を確かめる。"], ["セリオン", "同意する、と。……ただし、誰が何をしたかは消すな、とあります。"], ["", "俺は頷いた。"], ["", "それで、六つになった。"], ["", "鳥人の使いは、神へ祈る時にも川の約束を読み上げたいと書いていた。ドワーフの返事には、壊れた橋の金具の重さまで記されている。"], ["", "同じことを願っているわけではなかった。俺は一枚ずつ、その違いも写した。"], ["", "皆が戻ったら、祈りの場へもう一度寄る。"], ["", "荷をまとめ、紙を胸元へしまった。"]],"confession-road",null);
scene("prayer-return","CHAPTER 05","分岐B：仲間のもとへ戻り、明日の話をする",[["", "石から目を離し、俺は火のそばへ座った。"], ["ティア", "行かないのか。"], ["ミナト", "ああ。明日の道を、先に決めたい。"], ["", "ティアが肘をついて起き上がった。俺が広げた地図へ顔を寄せる。"], ["", "リーネも毛布の中から体を起こした。"], ["リーネ", "明日の村で、薬を買ってもいいですか。あと、聞いてみたい宿が。"], ["ミナト", "分かった。そこへ寄ろう。"], ["", "火を挟んで、セリオンが目を開けた。"], ["セリオン", "では出発は、鐘が鳴る前で。私も、尋ねたいことがあります。"], ["ティア", "全員、用があるんじゃないか。"], ["", "四人で地図を覗き込むと、俺の指していた道が見えなくなった。"]],"confession-road",null);
scene("confession-road","CHAPTER 06","塔へ向かう道",[["", "黒い塔が見えたのは、昼を過ぎてからだった。"], ["", "まだ遠い。それでも、リーネが足を止めるには十分だった。"], ["リーネ", "……あそこへ、行くんですか。"], ["ミナト", "ああ。"], ["", "ティアは塔を見ていた。山裾へ回り込む道と、崩れた斜面を順に確かめる。"], ["ティア", "道、一本しかないな。上から来られたら、ここじゃ避けられない。"], ["セリオン", "先に休む場所を探しましょう。"], ["ティア", "あの岩の裏なら、上からも見えにくい。"], ["", "俺たちは道を外れた。岩陰へ荷物を置いても、誰も座らなかった。"], ["", "リーネが俺の前へ来た。"], ["リーネ", "ミナトさん。"], ["ミナト", "……。"], ["リーネ", "ここに、探している方がいるんですか。"], ["", "俺は頷いた。"], ["", "リーネは塔へ目を戻した。目の前の俺より、そちらを見ている時間の方が長かった。"], ["リーネ", "災厄がいる場所だと、聞きました。"], ["", "ティアがこちらを向いた。セリオンは荷物から手を離した。"], ["ミナト", "そうだ。"], ["リーネ", "……では、なぜ、誰も討伐の話をしないんですか。"], ["", "言葉が続かなかった。リーネは俺が答えるのを待った。"], ["", "俺は腰の剣を外し、岩へ立てかけた。"]],"confession",null);
scene("confession","CHAPTER 06","黙っていた名前",[["ミナト","先に、話さなきゃいけないことがある。"],["","リーネは動かなかった。ティアが腕を組む。"],["ミナト","あそこにいるのは、カイルだ。"],["","風で、誰かの上着が鳴った。"],["リーネ","……兄、ですか。"],["ミナト","ああ。"],["","リーネはもう一度、塔を見た。それから俺を見た。"],["リーネ","ミナトさんは、兄を知っていたんですね。"],["ミナト","……友だ。"],["","ティアの腕がほどけた。セリオンは黙っていた。"],["ミナト","昔、行き倒れていた俺を助けてくれた。あいつがいなければ、とっくに死んでた。"],["リーネ","あの町で聞いた時も、知っていたんですか。"],["ミナト","ああ。"],["リーネ","どうして、言ってくれなかったんですか。"],["","俺は彼女の顔を見た。言葉を探している間にも、その目が赤くなっていく。"],["ミナト","助ける方法を、見つけてからにしたかった。"],["リーネ","……私は、待っていることも、選べなかったんですね。"],["ミナト","……。"],["","彼女は胸元へ手をやりかけ、下ろした。"],["ミナト","あの路地で助けたのも、偶然じゃない。妹を見ていてくれと、頼まれてた。"],["リーネ","それで、あそこに。"],["ミナト","ああ。"],["リーネ","私がついていくと言った時は、困ったんですか。"],["","返事が遅れた。"],["ミナト","……困った。"],["","リーネは俯いた。俺は手を伸ばしかけ、握ったまま下ろした。"],["ティア","待て。兄貴が、災厄になったって話か。"],["ミナト","そうだ。俺たちがヴァルゼンを倒した、その後に。"],["ティア","じゃあ、倒せば終わりじゃないんだな。"],["ミナト","倒しても、災厄は別の誰かへ移る。席が空いて、次の誰かが座るみたいにな。"],["","セリオンが、短く息を吐いた。"],["セリオン","……石の言葉は、そのことでしたか。"],["ミナト","ああ。あれだけじゃ、確かめようがなかっただろうが。"],["セリオン","今のお話も、誰から聞いたのかは、伺う必要があります。"],["ミナト","カイルだ。席に就いた後も、何度か会ってる。"],["","リーネの指が、服を握った。"],["リーネ","会えて、いたんですね。"],["ミナト","……ああ。"],["","今度は、言葉が途切れる前に続けた。この世界では、災厄になった者の名や顔が、人々の記憶から薄れていく。"],["ミナト","俺には、この世界の忘却が効かない。あいつが誰か、俺だけは見失わずにいられた。"],["セリオン","あなたがいたという所は……この世界ではないのですね。"],["ミナト","そうだ。"],["","セリオンは頷いた。驚かなかったが、納得した顔でもなかった。"],["","ティアは塔へ向き直り、すぐに俺へ目を戻した。"],["ティア","で、あいつを倒したら、次は誰だ。"],["ミナト","分からない。"],["ティア","……リーネか。"],["","リーネが顔を上げた。"],["ミナト","その可能性がある。妹で、あいつの近くにいる。今までの記録を見れば……。"],["セリオン","ただし、確定した規則ではありません。"],["ミナト","分かってる。"],["セリオン","皆さんにも、分かっていただくために言いました。選ばれると断定も、選ばれないと保証もできません。"],["","ティアが俺の前へ来た。"],["ティア","あたしらを連れてきたのは、そのためじゃないだろうな。"],["ミナト","違う。"],["","ティアは俺を見ていた。俺も、目を逸らさなかった。"],["ティア","……じゃあ、何で今まで黙ってた。"],["ミナト","戻らせるつもりだった。……結局、言えないまま、ここまで来た。"],["ティア","それを決めるのは、あんたじゃないだろ。"],["","言い返せなかった。リーネは、まだ服を握っている。"],["セリオン","少し、時間を取りましょう。今日は、まだ登れますか。"],["ミナト","無理をすれば。"],["セリオン","では、明日にしましょう。"],["","ティアも頷いた。俺の返事を待たず、岩の陰へ荷物を引いた。"]],null,[{"text": "すべてを話し、同行するかを彼女に委ねる", "to": "confession-honest", "rel": {"l": 2, "t": 1}, "fragments": [], "flags": {"honest": true}}, {"text": "危険だから、ここで待っていてほしいと告げる", "to": "confession-protect", "rel": {}, "fragments": [], "flags": {"honest": false}}]);
scene("confession-honest","CHAPTER 06","分岐A：すべてを話し、同行するかを彼女に委ねる",[["", "火を起こしてから、俺はリーネへ話した。"], ["", "何も持たず、この世界へ来た日のこと。最初の旅。ヴァルゼンを倒した後、あいつが妹から離れたこと。"], ["", "リーネは途中で二度、聞き返した。いつのことか。最後に会った時、どんな様子だったか。"], ["", "答えられることには、答えた。"], ["リーネ", "……今日は、もう聞けません。"], ["ミナト", "分かった。"], ["リーネ", "明日、私から聞いてもいいですか。"], ["ミナト", "ああ。"], ["", "リーネは火のそばへ座り直した。俺は少し離れた岩へ腰を下ろした。"]],"resolve",null);
scene("confession-protect","CHAPTER 06","分岐B：危険だから、ここで待っていてほしいと告げる",[["ミナト", "明日は、ここで待っていてくれ。"], ["", "リーネは俺を見た。返事はなかった。"], ["ミナト", "会うだけで済むとは限らない。もし、席が移ったら――。"], ["リーネ", "さっき、分からないと、言いましたよね。"], ["ミナト", "分からないから、危ないんだ。"], ["リーネ", "……はい。でも、私が何も知らないまま待つのは、危なくないんですか。"], ["ミナト", "……。"], ["リーネ", "兄のことを知っていたら、帰らなかったかもしれません。戻ったかもしれません。でも、考えることはできました。"], ["", "彼女は膝の上で手を重ねた。声が震えていたが、目は逸らさなかった。"], ["リーネ", "今夜は、一人にしてください。"], ["", "俺は頷いた。彼女の隣へ座ることも、できなかった。"]],"resolve",null);
scene("resolve","CHAPTER 06","誰の足で行くのか",[["", "夜明け前、リーネが俺のそばへ来た。"], ["リーネ", "あの時、一緒に行きたいと言ったのは、私です。"], ["ミナト", "ああ。"], ["リーネ", "でも、何も知らなくてよかったとは、思いません。"], ["", "俺は彼女へ向き直った。"], ["リーネ", "まだ、怒っています。今も、どうしていいか分からないです。"], ["リーネ", "……それでも、兄に会いたいです。"], ["", "少し後ろで、ティアが毛布を畳んでいた。"], ["ティア", "会ってから決めればいい。帰りたくなったら、あたしが道を空ける。"], ["", "リーネはティアを見た。それから俺を見る。"], ["リーネ", "私が話す時は、待っていてもらえますか。"], ["ミナト", "……ああ。"], ["ティア", "あたしは先に、あいつの動きを見る。いきなり斬りかかったりしないから、あんたも勝手に始めるなよ。"], ["ミナト", "分かった。"], ["", "ティアは俺の剣を持ち上げた。柄をこちらへ向けて差し出す。"], ["ティア", "あと、借りがまだ残ってるぞ。"], ["ミナト", "朝飯か。"], ["ティア", "それもだ。"], ["", "セリオンが荷物を締め終えた。"], ["セリオン", "戻ったら、続きをお願いします。"], ["ミナト", "……何の。"], ["セリオン", "押す力と、押し返す力。あの話を、まだ途中にしたままです。"], ["", "俺が答える前に、セリオンは立ち上がった。"], ["セリオン", "ですから、私も戻ります。あなたも、できれば。"], ["ティア", "できれば、じゃ困るだろ。"], ["セリオン", "ええ。では、必ず。"], ["", "リーネが少しだけ息を吐いた。笑ったのかどうかは、分からなかった。"], ["", "俺は剣を帯へ戻した。三人とも、まだこちらを見ていた。"], ["ミナト", "……もう一つ、決めなきゃいけない。"]],"resolve-plan",null);
scene("resolve-plan","CHAPTER 06","四つの道",[["ミナト", "席を壊すための手掛かりはある。だが、壊した後に何が起きるかは分からない。"], ["セリオン", "破壊の力が、そのまま散る危険もありますね。"], ["ミナト", "ああ。それに、人は争う相手を失えば、隣を見始める。"], ["ティア", "橋の奴らみたいにな。"], ["", "俺は頷いた。"], ["ミナト", "壊すなら、その前に話をつけたい。俺たちだけの話じゃ、済まない。"], ["セリオン", "返事をくれた方々に、まだ伝えていないことがあります。"], ["", "リーネは俺を見た。俺は彼女へ頷いた。"], ["ミナト", "そうだ。話す。誰が災厄なのかも、その妹がここにいることも。お前が、いいと言うなら。"], ["", "リーネは胸元の飾りを握った。しばらくして、手を離す。"], ["リーネ", "私のことは、私から話したいです。"], ["", "ティアは塔を見ていた。爪先で地面を一度掻く。"], ["ティア", "席が誰かを選ぶってんなら、選ぶ時まで、分からないんだな。"], ["ミナト", "……何を考えてる。"], ["ティア", "戦う相手のことだよ。"], ["", "俺はティアを見た。彼女は俺を見返したが、その先は言わなかった。"], ["", "四人の荷物の向こうで、火が消えかけていた。"]],null,[{"text": "皆の合意を求め、恐れで保つ席を不要にする", "to": "@plan", "rel": {}, "fragments": [], "flags": {"plan": "break"}}, {"text": "自分ひとりで、災厄の席を壊す", "to": "@plan", "rel": {}, "fragments": [], "flags": {"plan": "alone"}}, {"text": "ティアの覚悟に託し、戦場へ進む", "to": "@plan", "rel": {}, "fragments": [], "flags": {"plan": "tia"}}, {"text": "言葉にせず、友の選択を信じて待つ", "to": "@plan", "rel": {}, "fragments": [], "flags": {"plan": "wait"}}]);
scene("agreement-yes","CHAPTER 06","皆の合意を求める道：積み重ねが足りている場合",[["","手紙を出した。返事を待ち、こちらからも足を運んだ。"],["","ガレスは各地の使いを迎え、ユーリは歌を教わった土地へ連絡を取った。"],["","橋で会った使いも来た。最初に確かめられたのは、塔の話ではなく、川の約束を守るかどうかだった。"],["","俺は頷いた。それだけでは済まず、向こうの言葉で書いた約束も交わした。"],["","各地の使いが集まった部屋で、リーネは一度、俺の袖へ触れた。"],["リーネ","……少しだけ、隣にいてください。"],["ミナト","ああ。"],["","彼女は息を整え、前を向いた。"],["リーネ","あそこにいるのは、私の兄です。"],["","声は大きくなかった。誰かが身を乗り出したので、リーネは最初から言い直した。"],["リーネ","兄が災厄になったらしいと、聞きました。私はまだ、会えていません。"],["リーネ","皆さんが怖いと思う人を、私は探していました。……今も、会いたいです。"],["","部屋の後ろで、椅子が鳴った。ティアは扉のそばから、それを見ていた。"],["リーネ","もし次に私がそうなったら、私の話も、聞いてもらえますか。"],["","すぐに返事はなかった。川辺の使いが、隣の者へ小声で何か言った。"],["","話し合いは、その日だけでは終わらなかった。戻った者もいる。残って、言い合う者もいた。"],["","最後まで残った一人が、俺ではなくリーネへ向いた。"],["種族の使い","……聞く。まずは、それを約束する。"],["","リーネが頭を下げかけた。途中で止め、相手の顔を見て頷いた。"]],"agreement-method",null);
scene("agreement-method","CHAPTER 06","一人では引かない線",[["","話し合いの後、俺は剣と、刻印の写しを食卓へ置いた。"],["セリオン","……これを、災厄の席へ。"],["ミナト","閉じ込め直すんじゃなく、つながりを外したい。"],["","セリオンは紙を並べた。長い間、指を動かしていた。"],["セリオン","ここまでは、同じ形です。この先は、別のものにつながっています。"],["ミナト","全部、合わせられるか。"],["セリオン","合わせるだけなら。ですが、元が違う。働くとは、まだ言えません。"],["ティア","失敗した時は、どうする。"],["","俺は剣へ目を戻した。"],["ミナト","……誰か一人に、押しつけない。"],["ティア","それだけじゃ、動けないだろ。離れる合図を決めろ。続ける時もだ。"],["","リーネは紙の角を押さえていた。セリオンの手が止まると、俺を見た。"],["リーネ","兄と話している間は、待っていてください。"],["ミナト","ああ。"],["","夜が更けるまで、四人で紙を囲んだ。俺が線を描き足そうとすると、セリオンが二度、手を止めた。"],["セリオン","そこをつなぐと、別の働きになります。こちらの写しも、見てください。"],["","図がまとまってから、俺は剣を抜いた。紙と見比べながら、文字を彫るための細い鉄の棒で刃に刻印を彫っていく。"],["","刻み終えた剣を、紙の隣へ置いた。セリオンが一本ずつ線を確かめ、リーネとティアも覗き込んだ。"]],"battle-approach",null);
scene("agreement-no","CHAPTER 06","皆の合意を求める道：積み重ねが足りない場合",[["","返事を待った。来たのは、断りと、こちらの身元を確かめる問いだった。"],["","ガレスからの使いも、浮かない顔をしていた。招かれた者はいても、隣国の使いと同席する約束をしていない。"],["セリオン","聞いてもらう所までは、届きませんでした。"],["","机へ戻された紙の中に、橋の名があった。"],["","俺はその紙を畳んだ。リーネが何か言いかけたが、俺は席を立った。"]],"collapse-agreement",null);
scene("alone","CHAPTER 06","ひとりで決める道",[["","三人が休んでから、俺は剣を抜いた。"],["","持ってきた刻印の写しを、刃の横へ置く。力を失わせるための刻印。どこまで働くか、確かめた者はいない。"],["","火の消えた跡で、文字を彫るための細い鉄の棒を研いだ。"],["","俺がやればいい。"],["","そう思うと、手が動いた。刻印の写しの線を、刃へ刻んでいった。"]],"battle-approach",null);
scene("battle-approach","FINAL CHAPTER","約束した時間",[["", "塔へ近づくと、鳥の声が聞こえなくなった。"], ["", "石段に、深い溝が走っている。刃物で刻んだ跡ではなかった。"], ["", "ティアがしゃがんだ。溝の端を見て、塔の壁へ目を移す。"], ["ティア", "……外からじゃない。中から割れてる。"], ["ミナト", "近づくなよ。"], ["ティア", "触らない。こっちへ来る向きを見てるんだ。"], ["", "ティアはリーネの立つ場所を確かめ、石段の端へ寄った。"], ["", "上から、金属を引きずる音がした。"], ["", "リーネが俺の袖へ触れた。力はほとんど入っていなかった。"], ["ミナト", "分かってる。待つ。"], ["", "彼女は手を離した。"], ["", "階段を上りきると、天井のない部屋へ出た。崩れた壁の向こうに、雲が見える。"], ["", "男が一人、柱へ背を預けていた。"], ["", "俺を見ると、口元が緩んだ。それから、俺の後ろを見た。"], ["カイル", "……え。"], ["", "リーネが一歩、前へ出た。"], ["", "男は柱から体を離しかけた。足元の石が割れ、そこで止まる。"], ["カイル", "リーネ、か。"], ["リーネ", "……はい。"], ["", "カイルは彼女の顔を見ていた。何か言いかけ、笑おうとして、うまくいかなかった。"], ["カイル", "そうか。もう、そんなに大きくなったんだな。"], ["", "リーネの指が、服の横を掴んだ。"], ["リーネ", "兄は、冒険者になっていると、思っていました。"], ["カイル", "……うん。"], ["リーネ", "探しました。宿でも、町でも、聞いたんです。"], ["カイル", "うん。"], ["", "彼女は息を吸った。カイルの腰にある剣を見て、顔へ目を戻す。"], ["リーネ", "ここで、何をしているんですか。"], ["", "カイルの手が、柱の欠けた所へ触れた。指の下で、石が細かく崩れた。"], ["カイル", "……なるべく、じっとしてる。"], ["", "リーネは近づきかけた。カイルが手を上げる。"], ["カイル", "そこまで。もう少し、離れてて。"], ["リーネ", "私、回復の術を使えます。"], ["カイル", "聞いてる。ちゃんと、覚えたんだな。"], ["", "リーネが俺を見た。俺は何も言えなかった。"], ["リーネ", "……傷だけの話では、ないんですね。"], ["", "カイルは頷いた。"], ["", "彼女の手が上がった。けれど、術の光は出なかった。"], ["リーネ", "会いに来たら、分かると思っていました。"], ["カイル", "……。"], ["リーネ", "分からないことが、増えただけです。"], ["", "カイルの足元で、また石が鳴った。彼は剣の鞘を握った。"], ["", "ティアが半歩動いた。リーネの背中へ触れず、横から手を差し出す。"], ["ティア", "一歩、戻れ。そこ、次に割れる。"], ["", "リーネが下がると、さっき立っていた石へ亀裂が伸びた。"], ["カイル", "……悪い。あんまり、長く話せそうにない。"], ["", "俺はリーネを見た。彼女は兄を見たまま、頷いた。"], ["リーネ", "まだ、聞きたいことがあります。"], ["カイル", "うん。"], ["リーネ", "だから、私がここにいることを、嫌がらないでください。"], ["", "カイルの顔が歪んだ。リーネが、それでも目を逸らさなかった。"], ["カイル", "……嫌なわけ、ないだろ。"]],"battle",null);
scene("battle","FINAL CHAPTER","止めるための刃",[["","柱が砕けた。音より先に、カイルの肩が跳ねる。"],["","黒い筋が床を走った。カイルから漏れ出した災厄の力が、リーネへ迫る。その手前で、セリオンの術が黒い筋の端を押し返す。"],["セリオン","壁際へ。床の亀裂から目を離さないでください。"],["","ティアは前へ出なかった。カイルの剣と、割れた床を交互に見ている。"],["ティア","ミナト。あいつが剣を握り直す時、床が止まる。"],["ミナト","見えてる。"],["ティア","違う。止めてるんだ。自分で。次、待て。"],["","カイルが顔を上げた。剣を握る指が白くなっている。"],["カイル","……いい目だな。"],["","その瞬間だけ、床の軋みが止まった。"],["","俺は踏み込んだ。刃が合い、腕へ重さが返ってくる。"],["","カイルの剣が俺の肩をかすめた。避けた先の壁が、背後で崩れた。"],["ティア","右、来るぞ！"],["","俺は足を止めずに曲がった。ティアが投げた石が、次に崩れる床へ当たり、踏んではいけない場所を教える。"],["","戻る場所が見えた。俺はそこへ足を置き、もう一度カイルへ向かった。"],["","剣だけなら、何度も合わせてきた。踏み込む時の肩も、持ち直す時の肘も、知っていた。"],["","それでも、今は追いつかなかった。"],["","セリオンの術が軋んだ。リーネが彼の腕へ触れ、流れた血を止める。"],["リーネ","動かせますか。"],["セリオン","ええ。次は、手を離してください。巻き込みます。"],["","リーネはすぐに離れ、落ちた荷を壁際へ引いた。"],["","カイルは俺を追わなかった。壁の向こうへ向きかけた力を、自分の腕へ引き戻している。"],["カイル","ミナト。"],["","俺は構え直した。"],["カイル","……次は、長くない。"],["","握っていた剣の柄が、手の中で滑った。血を上着の袖で拭う。"],["","ティアがリーネの前を横切った。俺ではなく、カイルの目を見ていた。"],["ティア","あたしもいるぞ。忘れるな。"],["","カイルの視線が、ほんの一瞬、そちらへ動く。"],["","俺はその間へ入った。"],["","剣を押し返される。足を引けば、次はない。俺はもう半歩、前へ出た。"],["","刃を引くと、夜が静かになった。"],["","気づけば、壁の影が長く伸びていた。足元の揺れが止まっている。"],["","カイルの剣が落ちた。俺は肩を支え、一緒に膝をついた。"],["カイル","……どうしてリーネを連れてきたんだよ……ミナトのアホ"],["","リーネへ目を向けてから、あいつは俺を見た。"],["ミナト","すまん。"],["","言い訳を探す口が、もう動かなかった。"],["","リーネがそばへ来た。カイルの手を取り、傷口へもう片方の手を重ねる。"],["","光がこぼれた。カイルはそれを見て、困ったように笑った。"],["カイル","お前には普通に生きててほしかったんだけどな〜。"],["","リーネは答えなかった。震える手を、離さなかった。"],["","カイルの目が、彼女の向こうへ動いた。"],["","ティアはリーネより半歩、前にいた。戦いが止まっても、その位置を変えていない。"],["カイル","……ごめんね。妹のために。"],["ティア","勘違いするな。あたしは、災厄と戦いに来たんだ。"],["カイル","うん。"],["ティア","……。"],["カイル","ありがとう。"],["","カイルの指が、俺の袖を掴んだ。"],["","一度だけ、その力が強くなる。俺は頷かず、見返した。"],["","ほどけるまでの一瞬を、待った。"]],"$resolve",null);
scene("end_harmony","EPILOGUE","静かな調和",[["","カイルの手から、力が抜けた。"],["","リーネが体を強張らせた。兄の傷を押さえていた光が、指の間で潰れる。"],["リーネ","……何、これ。"],["","足元の欠片が弾けた。彼女は手を引き、カイルの体から離した。――移ったのだ。"],["リーネ","私、今……。"],["","小さな石が、もう一つ割れた。リーネは自分の手を抱えた。"],["リーネ","壊したいって。そんなこと、思ってないのに。"],["","俺は彼女へ手を伸ばした。触れた肩が、逃げるように揺れた。"],["リーネ","触らないで。……違うんです。嫌だからじゃなくて。"],["ミナト","分かってる。"],["","そう答えてから、俺は手を下ろした。分かっていても、何をすればいいか分からなかった。"],["","塔を離れてから、宿を断られるようになった。"],["","最初の宿では、主人がリーネの顔を見て、戸を閉めた。次の町では、入口に兵がいた。"],["リーネ","私、何もしていません。"],["","兵は俺に下がれと言った。彼女には、名前を尋ねなかった。"],["","山の小屋で寝泊まりした。水を汲み、火を起こし、薬を煮た。"],["","リーネは、自分の分の器を棚の端へ置いた。何度戻しても、同じ所へ置いた。"],["ミナト","ここでいい。"],["リーネ","……はい。"],["","次の日には、また端へ戻っていた。"],["","町へ食料を買いに出ると、討伐の布告が貼られていた。"],["","そこに、リーネの名はなかった。黒い塔の絵の下に、災厄とだけ書かれている。"],["","戻ると、戸の前に布包みがあった。ヴァルゼンが育てていたもののことが、続きとして書き足されていた。"],["","差出人の名はない。俺はそれを、最初の紙と一緒にしまった。"],["","リーネは火のそばに座っていた。縫いかけの布が、膝から落ちている。"],["ミナト","リーネ。"],["","少し遅れて、彼女が顔を上げた。"],["ミナト","今日、何か食べたか。"],["リーネ","……まだ。"],["","器を温め、目の前へ置いた。彼女は匙を取ったが、口へ運ばなかった。"],["リーネ","私、何を待っていたんでしょう。"],["","俺は隣へ座った。彼女の膝から落ちた布を、拾った。"],["","呼ぶと、振り向く日もあった。振り向かない日が増えた。"],["","そのたび、俺は同じ名前を呼んだ。"],["","ある朝、彼女は俺の手を見ていた。布を握る手を。そこに何があるのか、分からないように。"],["ミナト","……リーネ。"],["","目が合っても、何も戻らなかった。"],["","外では、討伐隊の鐘が鳴っていた。"]],"$harmony",null);
scene("end_sacrifice","EPILOGUE","君の敵になる",[["","カイルの指がほどける前に、ティアが一歩出た。"],["","リーネの手首を取り、兄の体からそっと離す。"],["ティア","……こっちにいろ。"],["","リーネが何か言うより先に、ティアの足元へ黒い筋が集まった。"],["","ティアは避けなかった。膝が折れかけても、踏みとどまった。"],["ティア","……っ、は。"],["","顔を上げる。笑おうとして、息が詰まった。"],["ティア","ほら。あたしの、勝ち。"],["","俺はカイルの体を下ろした。もう片方の腕で、崩れかけたティアを支える。"],["","その向こうで、カイルの目が閉じた。"],["","いつ移ったのか、見えなかった。なぜ彼女だったのかも、確かめるすべはなかった。"],["","ただ、俺の腕の中に、次の災厄がいた。"],["","塔を離れる頃、ティアは俺の肩から手を離した。"],["ティア","歩ける。"],["ミナト","無理するな。"],["ティア","無理じゃない。……今のうちは。"],["","歩くたび、爪先の石が砕けた。ティアはその都度、歩幅を変えた。"],["","峠に、大きな影が立っていた。ネイアは近づかなかった。"],["","ティアは一度だけそちらを見た。それから、前へ向き直った。"],["","次の町では、門が開かなかった。"],["","遠くから槍を向ける兵を、ティアは黙って見ていた。"],["兵","その者から離れろ。"],["","俺が動かないと、弓が上がった。"],["ティア","ミナト。退け。"],["ミナト","嫌だ。"],["ティア","……あたしなら、一人で。"],["ミナト","それも、嫌だ。"],["","矢が石へ当たった。俺は剣を抜かず、ティアと門の間へ立った。"],["","兵の目が変わった。俺にも、同じように槍を向け直す。"],["","ティアが俺の袖を掴んだ。"],["ティア","あんたまで、戻れなくなるぞ。"],["","俺はその手を取った。"],["ミナト","行こう。"],["","どこへ、とは言えなかった。ティアも聞かなかった。"],["","門から離れる間、背中へ石が飛んできた。振り向かなかった。"],["","友を救うための旅だった。"],["","今は、次の友と、閉じた門から離れている。"],["","道端で足を止めると、手が震えた。剣は、鞘に収めたままだった。"],["","ティアが何か言った。俺は返事をしようとして、声が出なかった。"]],"$sacrifice",null);
scene("collapse-agreement","CHAPTER 06","崩壊への接続：合意を求めたが得られなかった場合",[["","返事の来ない相手へ送った手紙の写しを、何度も開いた。"],["セリオン","まだ、待てます。"],["ミナト","……あいつは、いつまで待てる。"],["","セリオンは答えなかった。それを、俺は返事にした。"],["","夜、三人が休んでから、俺は剣を抜いた。"],["","刻印の写しを広げ、線を一つずつ刃へ移していく。"],["","刻み終えた時には、指の感覚がなくなっていた。"],["","誰にも見せず、鞘へ戻した。"]],"battle-approach",null);
scene("end_collapse","EPILOGUE","砕けた天秤",[["", "刃に刻んだ線が、カイルの血を吸った。"], ["", "握った手の中で、何かが砕けた。塔を押していた力が、急に消える。"], ["", "リーネが兄の名を呼んだ。俺は剣を見ていた。"], ["", "終わった。"], ["", "その言葉を、口にしかけた。"], ["セリオン", "……何を、したのですか。"], ["", "刃に残った欠片を、彼は見ていた。俺が何も言わないうちに、近づいてくる。"], ["セリオン", "それは、まだ確かめていないものです。いつ、刻んだのですか。"], ["ミナト", "……昨夜。"], ["セリオン", "なぜ、話してくださらなかったのですか。"], ["ミナト", "止めるだろ。"], ["", "彼の足が止まった。返事はなかった。"], ["", "ティアが俺の横を通り、リーネのそばへしゃがんだ。俺を見なかった。"], ["", "塔から戻ると、道の検問が増えていた。"], ["", "災厄が消えた、と誰かが告げた。だから兵を動かせる、と別の誰かが続けた。"], ["", "橋の向こうで、旗が上がった。以前は外していた橋が、今度は兵を渡すために戻された。"], ["", "村の入口には、避難する荷車が並んだ。自分の荷を下ろし、ほかの家の子どもを乗せる者がいた。"], ["", "ガレスへ使いを出した。返事より先に、別の町で火が上がった。"], ["", "魔族の旗の下に、ネイアが立っているという。"], ["", "俺が殺した相手の名を、あの声が問い直した。"], ["", "今度は、隣の国を敵と呼ぶ声に紛れていた。"], ["ミナト", "……終わらせたかったんだ。"], ["", "誰に言ったのか、自分でも分からなかった。"], ["", "セリオンが机に紙を置いた。俺が見せなかった刻印の、写しだった。"], ["セリオン", "私にも、考えさせてほしかった。"], ["", "彼は紙を残して出ていった。"], ["", "外から、荷車を呼ぶ声がした。俺は椅子に座ったまま、立てなかった。"]],"$collapse",null);
scene("end_true","EPILOGUE","名を呼ぶ朝",[["","カイルの指が、俺の袖から離れた。"],["","それでも、黒い筋は消えなかった。床を伝い、リーネの足元へ伸びていく。"],["","俺は、塔へ来る前の話し合いを思い出していた。"],["","ガレスの使いが運んできた紙を、集まった者たちで読んだ。一つの国にだけ、話を任せなかった。"],["","ユーリは歌の写しを広げた。窓を開けてほしいと歌われた者にも、暮らしがあったと話した。"],["","それだけで頷く者ばかりではなかった。災厄がいなくなれば、誰が次の戦を止めるのか。何度も聞かれた。"],["","俺一人が、争わないと約束しても意味がなかった。"],["","川辺の使いは、橋の約束を読み上げた。隣の国の者も、自分たちが守ることを、自分の言葉で答えた。"],["","リーネの話を聞くと約束した者もいた。彼女が災厄になったとしても、まずは聞くと。"],["","あの場で交わした言葉を、俺は覚えていた。"],["ミナト","リーネ。"],["","目の前で、彼女が顔を上げた。兄の手を握ったまま、人々の前で話した時と同じように、息を整える。"],["リーネ","……ここに、います。"],["","彼女は俺を見た。それから、自分の足元へ目を落とした。"],["リーネ","私は、ここにいます。"],["","俺は、伸びてくる黒い筋へ刃を向けた。刻印を確かめてくれた三人が、そばにいた。"],["","刃に刻んだ溝へ、黒い筋が触れた。"],["","セリオンが、その先を見ている。ティアはリーネの横で足を止め、俺を待っていた。"],["","息を吸い、刃を引いた。"],["","リーネへ伸びていた筋が途切れた。残った影も薄れ、床から消えていく。"],["","砕ける音はしなかった。"],["","壁の向こうを、風が通り抜けた。"],["","カイルの目は、もう開かなかった。"],["","リーネが口を開いた。声が出ず、兄の肩へ額をつけた。"],["","俺は剣を置いた。何か言おうとしたが、何も出なかった。"],["","夜が明けるまで、そこにいた。"],["","塔を下りた先に、小さな花が咲いていた。リーネはそれを見て、また泣いた。"],["","俺も、立ったままではいられなかった。"],["","数日後、橋のそばで朝を迎えた。"],["","ティアが鍋をかき混ぜていた。火へ薪を足しかけたリーネの手を、軽く止める。"],["ティア","今ので足りる。底が焦げるぞ。"],["リーネ","……はい。"],["","言ってから、リーネが少し笑った。"],["ティア","何だよ。"],["リーネ","何でもないです。"],["","セリオンが四つの器を並べた。俺の前だけ、縁の欠けた器だった。"],["ミナト","これ、まだ使うのか。"],["セリオン","ええ。縁が少し欠けただけですから。"],["","川向こうで、人が言い争っていた。渡る順番で揉めているらしい。"],["","ティアが顔を上げたが、リーネがパンを差し出すと、先にそちらを受け取った。"],["","争いがなくなったわけではない。"],["","あの人たちとまた会い、話さなければならない。ガレスも、ユーリも、ネイアも、それぞれの場所で待っている。"],["","リーネが空の椅子を見た。俺も、同じ所を見た。"],["","そこへ器を置くことは、しなかった。"],["","温かな粥を、四人で食べた。"]],"$true",null);
scene("end_god","EPILOGUE","神のいない空",[["","カイルの指が、俺の袖を強く掴んだ。"],["","目が合った。"],["","あいつが何を選ぶか。言葉にしたことは、一度もなかった。"],["","俺は袖を掴む手に、自分の手を重ねた。"],["","床を裂いていた力が、向きを変えた。リーネから逸れ、俺たちが上ってきた階段の方へ走っていく。"],["","塔へ入る前、入口の石床に刻んでおいた文字があった。"],["","祈りの場の石から取った写し。六つの種族が返した言葉と、それぞれの名。その中央に、アウレの名を置いた。"],["","黒い筋が階段を下り、入口の方から白い光が差した。"],["アウレ","……何を、した。"],["","声が、頭のすぐ後ろで響いた。"],["","リーネが顔を上げた。セリオンの筆が、袋から落ちる。"],["アウレ","そこは、私の――。"],["","最後の言葉が変わった。怒鳴ったのか、驚いたのか。耳が痛くなり、俺はカイルへ身を寄せた。"],["","あいつは空を見ていた。笑おうとして、血の混じった息を吐いた。"],["ミナト","……遅いんだよ。"],["","返事はなかった。あいつの指だけが、一度動いた。"],["","入口に刻み直した返事は、六つの種族から届いたものだった。"],["","祈って終わりにせず、誰が、何を引き受けるか。その名を、互いに知るための返事。"],["","その中央に、神の名があった。"],["アウレ","お前は、初めから……。"],["","声の勢いが落ちた。同じ言葉を続けようとして、途中で途切れる。"],["セリオン","……入口の刻印は、このために。"],["","俺は答えなかった。カイルの手を、両手で握り直した。"],["","あの時、水車の前で俺が何気なく話した、力の向き。"],["","覚えていたのは、俺だけではなかった。"],["","世界を創る神の力と、カイルに背負わせた破壊の力。カイルは、その二つをぶつけた。"],["","あいつは、それを神へ向けたのだった。"],["","空に、白い裂け目が走った。何かの顔に見えかけ、ただの光へ戻っていく。"],["アウレ","私は……。"],["","その先は、聞こえなかった。"],["","雨音のようなものが、遠くで続いた。声だったものが、もう言葉にならなかった。"],["","カイルの指が、ゆっくりほどけた。"],["ミナト","……おい。"],["","呼びかけた。名を呼んだ。頬へ触れても、目は開かなかった。"],["","俺はカイルの手を、自分の額へ押しつけた。"],["","勝った、とは言えなかった。"],["","帰り道、ネイアが峠に立っていた。空を見てから、俺へ目を落とす。"],["ネイア","……そうなったか。"],["","俺は頷いた。ネイアはそれ以上聞かなかった。"],["","リーネが、空へ顔を向けた。"],["リーネ","アウレ様は、もう、お話にならないんですね。"],["セリオン","……ええ。"],["リーネ","お名前は、覚えていましょう。"],["","俺は頷いた。神にも、友にも、言えなかったことがある。"],["","しばらくして、遠い山が鳴った。"],["","嵐も、揺れも、なくなりはしなかった。人々は天気を見て、川を測り、崩れた道を直した。"],["","それを、誰か一人のせいにはできなくなった。"],["","ガレスへ話した時、彼は長く黙っていた。最後に、紙へアウレの名を書いた。"],["","ユーリはその紙を見て、古い歌の末尾へ挟んだ。"],["","俺は二人の前で、ようやくカイルの最期を話した。"],["","声が続かなくなった。二人とも、続きを急かさなかった。"]],"$god",null);
scene("lonely","END ROUTE","誰もいない道",[["", "西門の鐘が鳴った。"], ["", "路地の方で、何かが壁に当たった。俺はそちらを見てから、荷車の後ろへついた。"], ["", "学者のセリオンを待たせている。今日を逃せば、また日がかかる。"], ["", "そう考えながら、門を出た。"], ["", "次の町で、薬を売る娘を見た。別人だった。"], ["", "俺は歩き出した。"], ["", "それからの旅で、セリオンとは会った。必要な文字を読んでもらい、礼を払った。"],  ["", "王都でも、辺境でも、長くは留まらなかった。"], ["", "黒い塔へ行ったのは、寒くなる少し前だった。そこで待っていたのは、災厄になった友のカイルだった。"], ["", "カイルは俺の後ろを見た。誰もいないことを確かめ、笑った。"], ["カイル", "……そっか。"], ["", "俺は聞き返さなかった。"], ["", "止めるために剣を抜いた。手を伸ばす相手も、後ろへ下がらせる相手もいなかった。"], ["", "カイルが動かなくなると、剣を収めた。夜になっていた。"], ["", "帰り道で、一人の少女を見た。"], ["", "白い服。直した鞄。道端の石に座っている。"], ["リーネ", "あの。"], ["", "俺が立ち止まると、少女は顔を上げた。"], ["リーネ", "この先の町に、泊まれる所はありますか。さっきの所では、だめだと言われて。"], ["", "胸元の小さな飾りを見た。"], ["ミナト", "……リーネ、か。"], ["", "彼女が立ち上がった。"], ["リーネ", "私を、ご存じなんですか。"], ["", "返事ができなかった。彼女の足元で、小石が音もなく割れた。"], ["", "俺は、その欠片を見た。"], ["リーネ", "……どうして、そんな顔を。"], ["", "腰の剣へ手を伸ばしかけたが、途中で止めた。"], ["", "あのとき、路地へ戻っていれば。ほんの数歩、引き返すだけだった。"],  ["", "少女が一歩下がった。俺は彼女の名を、もう一度呼んだ。"], ["", "数日後、リーネを探して孤児院へ行った。"], ["", "門を開けた者は、リーネの名を聞き返した。いた気がすると言う者はいても、はっきり覚えている者はいなかった。"], ["", "彼女が使っていた寝台には、別の子が眠っていた。"], ["", "俺は門の外へ出た。もう一度、名前を呼ぶ。"], ["", "返事はなかった。"], ["", "峠では、角と白い鱗を持つネイアが待っていた。剣を抜く音がする。"], ["", "俺も剣を抜いた。"], ["", "道は、まだ続いていた。"]],"$bad",null);

