function resolveEnding(st){if(st.flags.plan==='alone')return'collapse';if(st.flags.plan==='break')return ready(st)?'true':'collapse';if(st.flags.plan==='tia')return'sacrifice';if(ready(st)&&st.flags.contact&&st.flags.physics&&['record','song','stone','witness','contact'].every(f=>st.fragments.includes(f)))return'god';return'harmony';}

// 自動分岐は既存の選択効果を変更しない。
function canReceiveSix(st){
 const probe={...st,rel:{...st.rel,l:(st.rel.l||0)+2,t:(st.rel.t||0)+1},flags:{...st.flags,honest:true}};
 return ready(probe);
}
function resolveStoryTarget(id,st){
 if(id==='@six')return canReceiveSix(st)?'prayer-six':'confession-road';
 if(id==='@plan')return st.flags.plan==='break'?(ready(st)?'agreement-yes':'agreement-no'):st.flags.plan==='alone'?'alone':'battle-approach';
 return id;
}
function storyLine(node,line,st){
 const ref=PAGE_IDS[node]?.[line]||'';
 if(ref==='prayer-weeks-002'&&!st.flags.council)return['','川辺へ戻ると、荷運びの男が同じ箱の上に座っていた。橋は、まだ外されたままだった。'];
 return STORY[node].lines[line];
}

if(typeof module!=='undefined')module.exports={STORY,ENDINGS,ready,resolveEnding,PAGE_IDS,resolveStoryTarget,storyLine,canReceiveSix};
